/* Galeri contoh Slak 1.9.1: sama dengan galeri Contoh di Slak Studio. */
window.SLAK_EXAMPLES = [{"id":"tabungan","judul":"Kalkulator Tabungan","ikon":"💰","ringkas":"Slider, metric, dan grafik area.","kode":"sl.set_page_config({ page_title: \"Kalkulator Tabungan\" })\nsl.title(\"💰 Kalkulator Tabungan\")\n\nconst awal = sl.number_input(\"Setoran awal (Rp)\", { min: 0, value: 1000000, step: 100000 })\nconst bulanan = sl.slider(\"Setoran per bulan (Rp)\", 0, 5000000, 500000, 50000)\nconst bunga = sl.slider(\"Bunga per tahun (%)\", 0.0, 15.0, 5.0, 0.5)\nconst tahun = sl.select_slider(\"Lama menabung (tahun)\", [1, 2, 3, 5, 10, 15, 20], { value: 5 })\n\nconst r = bunga / 100 / 12\nlet saldo = awal, modal = awal\nconst data = []\nfor (let b = 1; b <= tahun * 12; b++) {\n  saldo = saldo * (1 + r) + bulanan\n  modal += bulanan\n  if (b % 12 === 0) data.push({ tahun: b / 12, modal, saldo: Math.round(saldo) })\n}\n\nconst rp = (v) => \"Rp \" + Math.round(v).toLocaleString(\"id-ID\")\nconst [a, b, c] = sl.columns(3)\na.metric(\"Saldo akhir\", rp(saldo))\nb.metric(\"Total setoran\", rp(modal))\nc.metric(\"Hasil bunga\", rp(saldo - modal), \"+\" + ((saldo / modal - 1) * 100).toFixed(1) + \"%\")\n\nsl.area_chart(data, { x: \"tahun\", y: [\"modal\", \"saldo\"], x_label: \"Tahun\" })\n"},{"id":"dashboard","judul":"Dasbor Penjualan","ikon":"📊","ringkas":"Sidebar, filter, tab, dan tabel.","kode":"sl.set_page_config({ page_title: \"Dasbor Penjualan\", layout: \"wide\" })\n\nconst buat = sl.cache_data(() => {\n  const wilayah = [\"Jayapura\", \"Sorong\", \"Merauke\", \"Manokwari\", \"Timika\"]\n  const produk = [\"Kopi\", \"Sagu\", \"Matoa\", \"Noken\"]\n  const rows = []\n  let seed = 7\n  const acak = () => (seed = (seed * 9301 + 49297) % 233280) / 233280\n  for (let bulan = 1; bulan <= 12; bulan++)\n    for (const w of wilayah)\n      for (const p of produk)\n        rows.push({ bulan, wilayah: w, produk: p, unit: Math.round(20 + acak() * 80 + bulan * 3), harga: { Kopi: 45000, Sagu: 20000, Matoa: 35000, Noken: 150000 }[p] })\n  return rows\n})\nconst semua = buat()\n\nsl.sidebar.header(\"Filter\")\nconst wil = sl.sidebar.multiselect(\"Wilayah\", [\"Jayapura\", \"Sorong\", \"Merauke\", \"Manokwari\", \"Timika\"], { default: [\"Jayapura\", \"Sorong\", \"Merauke\"] })\nconst [b0, b1] = sl.sidebar.slider(\"Bulan\", 1, 12, [1, 12])\nconst data = semua.filter(r => wil.includes(r.wilayah) && r.bulan >= b0 && r.bulan <= b1)\n\nsl.title(\"📊 Dasbor Penjualan\")\nsl.caption(`${data.length} transaksi · bulan ${b0}–${b1}`)\n\nconst omzet = data.reduce((t, r) => t + r.unit * r.harga, 0)\nconst unit = data.reduce((t, r) => t + r.unit, 0)\nconst [m1, m2, m3] = sl.columns(3)\nm1.metric(\"Omzet\", \"Rp \" + (omzet / 1e6).toFixed(1) + \" jt\", null, { border: true })\nm2.metric(\"Unit terjual\", unit, null, { border: true })\nm3.metric(\"Wilayah\", wil.length, null, { border: true })\n\nconst perBulan = []\nfor (let b = b0; b <= b1; b++) {\n  const row = { bulan: b }\n  for (const p of [\"Kopi\", \"Sagu\", \"Matoa\", \"Noken\"]) row[p] = data.filter(r => r.bulan === b && r.produk === p).reduce((t, r) => t + r.unit, 0)\n  perBulan.push(row)\n}\nconst perWil = wil.map(w => ({ wilayah: w, unit: data.filter(r => r.wilayah === w).reduce((t, r) => t + r.unit, 0) }))\n\nconst [t1, t2, t3] = sl.tabs([\"Tren\", \"Per wilayah\", \"Data\"])\nt1.line_chart(perBulan, { x: \"bulan\", x_label: \"Bulan\" })\nt2.bar_chart(perWil, { x: \"wilayah\" })\nt3.dataframe(data, { hide_index: true })\n"},{"id":"todo","judul":"Daftar Tugas","ikon":"✅","ringkas":"session_state, form, dan checkbox dengan key.","kode":"sl.title(\"✅ Daftar Tugas\")\nconst ss = sl.session_state\nif (!ss.tugas) ss.tugas = [\n  { id: 1, teks: \"Belajar Slak\", selesai: true },\n  { id: 2, teks: \"Membuat aplikasi pertama\", selesai: false }\n]\n\nconst f = sl.form(\"tambah\", { clear_on_submit: true, border: false })\nconst [a, b] = f.columns([4, 1], { vertical_alignment: \"bottom\" })\nconst baru = a.text_input(\"Tugas baru\", { placeholder: \"Apa yang mau dikerjakan?\", label_visibility: \"collapsed\" })\nif (b.form_submit_button(\"Tambah\", { type: \"primary\", use_container_width: true }) && baru.trim()) {\n  ss.tugas.push({ id: Date.now(), teks: baru.trim(), selesai: false })\n}\n\nconst filter = sl.radio(\"Tampilkan\", [\"Semua\", \"Belum\", \"Selesai\"], { horizontal: true, label_visibility: \"collapsed\" })\nconst daftar = ss.tugas.filter(t => filter === \"Semua\" || (filter === \"Selesai\") === t.selesai)\n\nfor (const t of daftar) {\n  const [c1, c2] = sl.columns([6, 1], { vertical_alignment: \"center\" })\n  t.selesai = c1.checkbox(t.teks, { value: t.selesai, key: \"t\" + t.id })\n  c2.button(\"Hapus\", { key: \"h\" + t.id, on_click: () => { ss.tugas = ss.tugas.filter(x => x.id !== t.id) } })\n}\n\nconst sisa = ss.tugas.filter(t => !t.selesai).length\nsl.caption(sisa ? `${sisa} tugas belum selesai` : \"Semua tugas beres 🎉\")\n"},{"id":"kuis","judul":"Kuis Pengetahuan","ikon":"🧠","ringkas":"Radio, form, dan skor.","kode":"sl.title(\"🧠 Kuis Papua\")\nconst soal = [\n  { q: \"Danau terbesar di Papua?\", o: [\"Danau Sentani\", \"Danau Paniai\", \"Danau Toba\"], a: 1 },\n  { q: \"Burung khas Papua yang terkenal?\", o: [\"Cenderawasih\", \"Jalak Bali\", \"Merak\"], a: 0 },\n  { q: \"Makanan pokok dari sagu?\", o: [\"Gudeg\", \"Papeda\", \"Rendang\"], a: 1 },\n  { q: \"Kepulauan wisata selam terkenal?\", o: [\"Wakatobi\", \"Raja Ampat\", \"Karimunjawa\"], a: 1 }\n]\n\nconst f = sl.form(\"kuis\")\nconst jawab = soal.map((s, i) => f.radio(`${i + 1}. ${s.q}`, s.o, { index: null }))\nconst kirim = f.form_submit_button(\"Periksa jawaban\", { type: \"primary\" })\n\nif (kirim) {\n  if (jawab.includes(null)) sl.warning(\"Jawab semua soal dulu ya.\")\n  else {\n    const benar = jawab.filter((j, i) => j === soal[i].o[soal[i].a]).length\n    sl.metric(\"Skor\", `${benar} / ${soal.length}`)\n    if (benar === soal.length) { sl.success(\"Sempurna!\"); sl.balloons() }\n    else soal.forEach((s, i) => { if (jawab[i] !== s.o[s.a]) sl.info(`Soal ${i + 1}: jawabannya **${s.o[s.a]}**`) })\n  }\n}\n"},{"id":"satuan","judul":"Konverter Satuan","ikon":"📏","ringkas":"Selectbox dinamis dan objek data.","kode":"sl.title(\"📏 Konverter Satuan\")\nconst SATUAN = {\n  Panjang: { meter: 1, kilometer: 1000, sentimeter: 0.01, mil: 1609.344, kaki: 0.3048, inci: 0.0254 },\n  Berat: { kilogram: 1, gram: 0.001, ton: 1000, pon: 0.453592, ons: 0.1 },\n  Waktu: { detik: 1, menit: 60, jam: 3600, hari: 86400, minggu: 604800 }\n}\n\nconst jenis = sl.radio(\"Jenis\", Object.keys(SATUAN), { horizontal: true })\nconst daftar = Object.keys(SATUAN[jenis])\nconst [a, b, c] = sl.columns([2, 2, 2], { vertical_alignment: \"bottom\" })\nconst nilai = a.number_input(\"Nilai\", { value: 1, step: 0.1 })\nconst dari = b.selectbox(\"Dari\", daftar, { key: \"dari-\" + jenis })\nconst ke = c.selectbox(\"Ke\", daftar, { index: 1, key: \"ke-\" + jenis })\n\nconst hasil = nilai * SATUAN[jenis][dari] / SATUAN[jenis][ke]\nsl.metric(`${nilai} ${dari} =`, `${+hasil.toPrecision(8)} ${ke}`)\n\nsl.table(daftar.map(s => ({ satuan: s, nilai: +(nilai * SATUAN[jenis][dari] / SATUAN[jenis][s]).toPrecision(8) })))\n"},{"id":"gelombang","judul":"Animasi Gelombang","ikon":"🌊","ringkas":"Grafik yang bergerak dengan await.","kode":"sl.title(\"🌊 Gelombang\")\nconst frek = sl.slider(\"Frekuensi\", 0.5, 5.0, 1.5, 0.1)\nconst amp = sl.slider(\"Amplitudo\", 1, 10, 5)\nconst jalan = sl.toggle(\"Animasikan\", true)\n\nconst grafik = sl.empty()\nconst info = sl.empty()\nlet t = 0\ndo {\n  const data = Array.from({ length: 80 }, (_, i) => {\n    const x = i / 8\n    return { x: +x.toFixed(2), sinus: amp * Math.sin(frek * x + t), kosinus: amp * 0.6 * Math.cos(frek * x * 0.5 - t) }\n  })\n  grafik.line_chart(data, { x: \"x\", height: 320 })\n  info.caption(\"t = \" + t.toFixed(2))\n  t += 0.15\n  if (jalan) await sl.sleep(60)\n} while (jalan)\n"},{"id":"chat","judul":"Bot Chat","ikon":"💬","ringkas":"chat_message, chat_input, dan spinner.","kode":"sl.title(\"💬 Bot Pantun\")\nconst ss = sl.session_state\nconst PANTUN = [\n  \"Pergi ke pasar membeli sagu,\\nSagu dibawa ke Kampung Harapan.\\nKalau kamu sedang menunggu,\\nSlak membuat aplikasi tanpa hambatan.\",\n  \"Burung cenderawasih terbang tinggi,\\nHinggap sebentar di pohon matoa.\\nBelajar kode setiap hari,\\nLama-lama jadi ahli juga.\",\n  \"Ke Raja Ampat naik perahu,\\nLihat ikan warna-warni.\\nKalau kode belum menentu,\\nCoba jalankan sekali lagi.\"\n]\nif (!ss.log) ss.log = [{ r: \"assistant\", t: \"Ketik apa saja, aku balas dengan pantun! 🌺\" }]\nfor (const m of ss.log) sl.chat_message(m.r).markdown(m.t.replaceAll(\"\\n\", \"  \\n\"))\n\nconst q = sl.chat_input(\"Ketik pesan…\")\nif (q) {\n  ss.log.push({ r: \"user\", t: q })\n  sl.chat_message(\"user\").markdown(q)\n  const box = sl.chat_message(\"assistant\")\n  await box.spinner(\"Merangkai pantun…\", () => sl.sleep(600))\n  const p = PANTUN[ss.log.length % PANTUN.length]\n  box.markdown(p.replaceAll(\"\\n\", \"  \\n\"))\n  ss.log.push({ r: \"assistant\", t: p })\n}\n"},{"id":"kasir","judul":"Kasir Toko","ikon":"🛒","ringkas":"Multi-halaman, database, dan data_editor.","kode":"sl.set_page_config({ page_title: \"Kasir Toko\", page_icon: \"🛒\", layout: \"wide\" })\nconst db = sl.db(\"kasir\", { produk: \"++id, nama\", penjualan: \"++id, tanggal\" })\nconst ss = sl.session_state\nif (!ss.keranjang) ss.keranjang = []\nconst rp = (v) => \"Rp \" + Math.round(v).toLocaleString(\"id-ID\")\n\n// Data awal, hanya diisi sekali\nif (await db.produk.count() === 0) {\n  await db.produk.insert([\n    { nama: \"Kopi Wamena\", harga: 45000, stok: 20 },\n    { nama: \"Sagu Lempeng\", harga: 15000, stok: 40 },\n    { nama: \"Buah Matoa\", harga: 30000, stok: 25 },\n    { nama: \"Noken Kecil\", harga: 120000, stok: 8 }\n  ])\n}\n\nasync function kasir(sl) {\n  sl.title(\"🛒 Kasir\")\n  const produk = await db.produk.all()\n  const byId = Object.fromEntries(produk.map(p => [p.id, p]))\n  const [kiri, kanan] = sl.columns([3, 2], { gap: \"large\" })\n\n  const id = kiri.selectbox(\"Produk\", produk.map(p => p.id), { format_func: (i) => byId[i] ? `${byId[i].nama} — ${rp(byId[i].harga)} (stok ${byId[i].stok})` : \"\" })\n  const jumlah = kiri.number_input(\"Jumlah\", { min: 1, value: 1 })\n  if (kiri.button(\"Tambah ke keranjang\", { type: \"primary\" }) && byId[id]) {\n    ss.keranjang.push({ id, nama: byId[id].nama, harga: byId[id].harga, jumlah })\n  }\n\n  kanan.subheader(\"Keranjang\")\n  if (!ss.keranjang.length) { kanan.info(\"Keranjang masih kosong.\"); return }\n  kanan.table(ss.keranjang.map(k => ({ produk: k.nama, jumlah: k.jumlah, subtotal: rp(k.harga * k.jumlah) })), { hide_index: true })\n  const total = ss.keranjang.reduce((t, k) => t + k.harga * k.jumlah, 0)\n  kanan.metric(\"Total\", rp(total))\n\n  const [b1, b2] = kanan.columns(2)\n  if (b2.button(\"Kosongkan\")) { ss.keranjang = []; sl.rerun() }\n  if (b1.button(\"Bayar\", { type: \"primary\" })) {\n    const kurang = ss.keranjang.find(k => k.jumlah > (byId[k.id] ? byId[k.id].stok : 0))\n    if (kurang) { kanan.error(`Stok ${kurang.nama} tidak cukup.`); return }\n    const tanggal = new Date().toISOString().slice(0, 10)\n    for (const k of ss.keranjang) {\n      await db.penjualan.insert({ tanggal, produk: k.nama, jumlah: k.jumlah, total: k.harga * k.jumlah })\n      await db.produk.update(k.id, (p) => ({ ...p, stok: p.stok - k.jumlah }))\n    }\n    ss.keranjang = []\n    sl.toast(\"Pembayaran berhasil: \" + rp(total), \"✓\")\n    sl.balloons()\n  }\n}\n\nasync function produk(sl) {\n  sl.title(\"📦 Produk\")\n  sl.caption(\"Klik sel untuk mengubah, + Tambah baris untuk produk baru, × untuk menghapus. Perubahan langsung tersimpan.\")\n  await sl.data_editor(db.produk, {\n    column_config: {\n      nama: { label: \"Nama produk\", required: true },\n      harga: { label: \"Harga (Rp)\", type: \"number\", min: 0 },\n      stok: { label: \"Stok\", type: \"number\", min: 0 }\n    }\n  })\n}\n\nasync function laporan(sl) {\n  sl.title(\"📈 Laporan\")\n  const jual = await db.penjualan.orderBy(\"id\", \"desc\").all()\n  const [m1, m2, m3] = sl.columns(3)\n  m1.metric(\"Omzet\", rp(jual.reduce((t, j) => t + j.total, 0)), null, { border: true })\n  m2.metric(\"Barang terjual\", jual.reduce((t, j) => t + j.jumlah, 0), null, { border: true })\n  m3.metric(\"Transaksi\", jual.length, null, { border: true })\n  if (!jual.length) { sl.info(\"Belum ada penjualan. Coba bayar di halaman Kasir.\"); return }\n  const per = {}\n  for (const j of jual) per[j.produk] = (per[j.produk] || 0) + j.total\n  sl.bar_chart(Object.entries(per).map(([produk, omzet]) => ({ produk, omzet })), { x: \"produk\", title: \"Omzet per produk\" })\n  sl.dataframe(jual, { hide_index: true })\n  sl.download_button(\"Unduh CSV\", sl.to_csv(jual), { file_name: \"penjualan.csv\", mime: \"text/csv\" })\n}\n\nawait sl.navigation([\n  sl.page(\"Kasir\", kasir, { icon: \"🛒\" }),\n  sl.page(\"Produk\", produk, { icon: \"📦\" }),\n  sl.page(\"Laporan\", laporan, { icon: \"📈\" })\n]).run()\n"},{"id":"jurnal","judul":"Jurnal Harian","ikon":"📔","ringkas":"local_state: catatan tetap ada walau ditutup.","kode":"sl.title(\"📔 Jurnal Harian\")\nsl.caption(\"Catatanmu tersimpan di browser ini, walau halaman ditutup.\")\nconst ls = sl.local_state\nif (!ls.jurnal) ls.jurnal = []\n\nconst f = sl.form(\"tulis\", { clear_on_submit: true })\nconst tgl = f.date_input(\"Tanggal\")\nconst suasana = f.radio(\"Suasana hati\", [\"😄\", \"🙂\", \"😐\", \"😕\", \"😢\"], { horizontal: true, index: 1 })\nconst isi = f.text_area(\"Cerita hari ini\", { placeholder: \"Apa yang terjadi hari ini?\" })\nif (f.form_submit_button(\"Simpan\", { type: \"primary\" })) {\n  if (!isi.trim()) sl.warning(\"Tulis ceritanya dulu.\")\n  else { ls.jurnal.unshift({ id: Date.now(), tgl, suasana, isi }); sl.toast(\"Tersimpan\", \"📔\") }\n}\n\nsl.subheader(ls.jurnal.length + \" catatan\")\nconst cari = sl.text_input(\"Cari\", { placeholder: \"kata kunci…\", live: true, persist: true })\nconst hasil = ls.jurnal.filter(j => !cari || j.isi.toLowerCase().includes(cari.toLowerCase()))\nfor (const j of hasil) {\n  const box = sl.container({ border: true, key: \"j\" + j.id })\n  box.markdown(`**${j.suasana} ${j.tgl}**  \\n${j.isi}`)\n  box.button(\"Hapus\", { key: \"hapus\" + j.id, on_click: () => { ls.jurnal = ls.jurnal.filter(x => x.id !== j.id) } })\n}\n"},{"id":"penjelajah","judul":"Penjelajah Data","ikon":"🧭","ringkas":"Unggah CSV/Excel, lihat profil kolom, korelasi, dan unduh data bersih.","kode":"sl.set_page_config({ page_title: \"Penjelajah Data\", layout: \"wide\" })\nsl.title(\"🧭 Penjelajah Data\")\nsl.caption(\"Unggah CSV atau Excel, atau pilih dataset contoh. Semua diproses di browser; data tidak dikirim ke mana pun.\")\n\nconst berkas = sl.sidebar.file_uploader(\"Berkas data\", { type: [\"csv\", \"tsv\", \"txt\", \"xlsx\", \"json\"] })\nconst contoh = sl.sidebar.selectbox(\"Atau dataset contoh\", sl.datasets().nama.to_list(), { index: 0, disabled: !!berkas })\n\nlet df\nif (berkas && /\\.xlsx$/i.test(berkas.name)) {\n  const sheets = await sl.excel_sheets(berkas)\n  const sheet = sl.sidebar.selectbox(\"Sheet\", sheets)\n  df = await sl.read_excel(berkas, { sheet })\n} else if (berkas && /\\.json$/i.test(berkas.name)) df = await sl.read_json(berkas)\nelse if (berkas) df = await sl.read_csv(berkas)\nelse df = sl.dataset(contoh)\n\nif (sl.sidebar.toggle(\"Rapikan nama kolom & spasi\", false)) df = df.clean_names().strip_strings()\nif (sl.sidebar.toggle(\"Buang baris duplikat\", false)) df = df.drop_duplicates()\n\nconst [a, b, c, d] = sl.columns(4)\na.metric(\"Baris\", df.length.toLocaleString(\"id-ID\"))\nb.metric(\"Kolom\", df.columns.length)\nc.metric(\"Sel kosong\", df.isna().sum().sum())\nd.metric(\"Duplikat\", df.duplicated().sum())\n\nconst [t1, t2, t3, t4] = sl.tabs([\"Data\", \"Profil kolom\", \"Satu kolom\", \"Korelasi\"])\nt1.dataframe(df, { height: 420 })\nt1.download_button(\"⤓ Unduh CSV\", df, { file_name: \"data_bersih.csv\" })\nt1.download_button(\"⤓ Unduh Excel\", df, { file_name: \"data_bersih.xlsx\" })\n\nt2.dataframe(df.info(), { hide_index: true })\nt2.dataframe(df.describe(), { hide_index: true })\n\nconst kolom = t3.selectbox(\"Pilih kolom\", df.columns)\nconst s = df.col(kolom)\nif ([\"int\", \"number\"].includes(s.dtype)) {\n  const [k1, k2] = t3.columns(2)\n  k1.histogram(df, { x: kolom })\n  k2.box_plot(df, { y: kolom })\n  const p = s.outliers()\n  t3.caption(`Pencilan (metode IQR): ${p.sum()} nilai di luar ${p.bounds.map(v => v.toLocaleString(\"id-ID\", { maximumFractionDigits: 2 })).join(\" sampai \")}.`)\n} else if (s.dtype === \"date\") {\n  t3.line_chart(df.resample(kolom, \"M\").size(), { x: kolom, y: \"jumlah\", title: \"Jumlah baris per bulan\" })\n} else {\n  t3.bar_chart(s.value_counts().head(20), { x: kolom, y: \"jumlah\", horizontal: true, labels: true })\n}\n\nconst num = df.select_dtypes(\"angka\")\nif (num.columns.length >= 2) t4.heatmap(num.corr(), { title: \"Korelasi Pearson\", min: -1, max: 1 })\nelse t4.info(\"Butuh minimal dua kolom angka untuk korelasi.\")\n"},{"id":"portofolio_penjualan","judul":"Portofolio Analisis Penjualan","ikon":"🏆","ringkas":"Dasbor multi-halaman: KPI, tren, SQL, kohort, RFM, dan temuan.","kode":"sl.set_page_config({ page_title: \"Analisis Penjualan · Portofolio\", page_icon: \"🏆\", layout: \"wide\" })\nconst semua = sl.dataset(\"penjualan\")   // ganti dengan: await sl.read_csv(\"penjualan.csv\")\n\nsl.sidebar.markdown(\"### Filter\")\nconst kota = sl.sidebar.multiselect(\"Kota\", semua.unique(\"kota\"), { default: semua.unique(\"kota\") })\nconst kanal = sl.sidebar.radio(\"Kanal\", [\"Semua\", \"Online\", \"Toko\"])\nlet df = semua.filter(semua.kota.isin(kota))\nif (kanal !== \"Semua\") df = df.query(\"kanal == @kanal\", { kanal })\nconst rp = v => \"Rp \" + (v / 1e6).toLocaleString(\"id-ID\", { maximumFractionDigits: 1 }) + \" jt\"\n\nfunction ringkasan(sl) {\n  sl.title(\"🏆 Analisis Penjualan Toko 2023–2024\")\n  sl.markdown(\"**Pertanyaan bisnis:** kota, produk, dan pelanggan mana yang paling berharga, dan bagaimana trennya?\")\n  const th = y => df.query(\"year(tanggal) == @y\", { y })\n  const [a, b, c, d] = sl.columns(4)\n  const o23 = th(2023).total.sum(), o24 = th(2024).total.sum()\n  a.metric(\"Omzet 2024\", rp(o24), ((o24 / o23 - 1) * 100).toFixed(1) + \"% vs 2023\", { border: true })\n  b.metric(\"Transaksi\", df.id_transaksi.nunique().toLocaleString(\"id-ID\"), null, { border: true })\n  c.metric(\"Pelanggan\", df.pelanggan_id.nunique(), null, { border: true })\n  d.metric(\"Rata-rata per transaksi\", rp(df.total.sum() / df.id_transaksi.nunique()), null, { border: true })\n\n  const bulanan = df.resample(\"tanggal\", \"M\").agg({ omzet: [\"total\", \"sum\"] })\n  sl.line_chart(bulanan.assign({ tren: () => bulanan.omzet.rolling(3).mean() }), { x: \"tanggal\", y: [\"omzet\", \"tren\"], title: \"Omzet bulanan dan tren 3 bulan\", format: \"compact\" })\n\n  const [k1, k2] = sl.columns(2)\n  k1.bar_chart(df.groupby(\"kota\").agg({ omzet: [\"total\", \"sum\"] }), { x: \"kota\", y: \"omzet\", horizontal: true, sort: true, title: \"Omzet per kota\", format: \"compact\", labels: true })\n  k2.pie_chart(df, { names: \"kategori\", values: \"total\", donut: true, title: \"Porsi kategori\", format: \"compact\" })\n}\n\nasync function produk(sl) {\n  sl.title(\"📦 Produk\")\n  const top = await sl.sql(`\n    WITH r AS (\n      SELECT kota, produk, SUM(total) AS omzet,\n             RANK() OVER (PARTITION BY kota ORDER BY SUM(total) DESC) AS peringkat\n      FROM penjualan GROUP BY kota, produk)\n    SELECT kota, produk, omzet FROM r WHERE peringkat <= 3 ORDER BY kota, omzet DESC`, { penjualan: df })\n  sl.subheader(\"Tiga produk teratas per kota (SQL)\")\n  sl.dataframe(top, { hide_index: true, format: { omzet: \"rupiah\" }, gradient: [\"omzet\"] })\n  const par = sl.analysis.pareto(df, { category: \"produk\", value: \"total\" })\n  sl.combo_chart(par, { x: \"produk\", bar: \"total\", line: \"persen_kumulatif\", title: \"Pareto produk (garis = persen kumulatif)\" })\n  sl.caption(`${par.query(\"kelas == 'A'\").length} dari ${par.length} produk menyumbang 80% omzet (kelas A).`)\n}\n\nfunction pelanggan(sl) {\n  sl.title(\"👥 Pelanggan\")\n  const ko = sl.analysis.cohort(df, { customer: \"pelanggan_id\", date: \"tanggal\", max_periods: 12 })\n  sl.heatmap(ko.drop(\"ukuran\"), { title: \"Retensi kohort bulanan\", format: \"percent:0\" })\n  const rfm = sl.analysis.rfm(df, { customer: \"pelanggan_id\", date: \"tanggal\", amount: \"total\" })\n  const seg = rfm.groupby(\"segmen\").agg({ pelanggan: [\"pelanggan_id\", \"count\"], omzet: [\"monetary\", \"sum\"] }).sort_values(\"omzet\", { ascending: false })\n  sl.bar_chart(seg, { x: \"segmen\", y: \"omzet\", horizontal: true, title: \"Omzet per segmen RFM\", format: \"compact\", labels: true })\n  sl.dataframe(seg, { hide_index: true, format: { omzet: \"rupiah\" } })\n}\n\nfunction temuan(sl) {\n  sl.title(\"💡 Temuan & rekomendasi\")\n  sl.markdown(`\n1. **Jayapura** adalah pasar terbesar; perluas kanal online di sana.\n2. Omzet memuncak di **Desember** dan bulan **Ramadan**; siapkan stok lebih awal.\n3. **Kopi Papua 250g** sendiri menyumbang sekitar seperempat omzet; jaga ketersediaannya.\n4. Segmen **Berisiko** dan **Jangan Sampai Hilang** layak mendapat kampanye retensi.\n\n*Metode: data transaksi dibersihkan dan dianalisis dengan Slak (groupby, SQL, kohort, RFM, Pareto).*`)\n}\n\nsl.navigation([\n  sl.page(\"Ringkasan\", ringkasan, { icon: \"📊\" }),\n  sl.page(\"Produk\", produk, { icon: \"📦\" }),\n  sl.page(\"Pelanggan\", pelanggan, { icon: \"👥\" }),\n  sl.page(\"Temuan\", temuan, { icon: \"💡\" })\n]).run()\n"},{"id":"churn","judul":"Prediksi Churn","ikon":"🤖","ringkas":"Latih model, bandingkan, evaluasi, lalu coba prediksi \"bagaimana jika\".","kode":"sl.set_page_config({ page_title: \"Prediksi Churn\", layout: \"wide\" })\nsl.title(\"🤖 Prediksi pelanggan berhenti (churn)\")\nconst df = sl.dataset(\"pelanggan\").drop(\"pelanggan_id\")\n\nconst jenis = sl.sidebar.selectbox(\"Model\", [\"Random forest\", \"Regresi logistik\", \"Pohon keputusan\", \"KNN\", \"Naive Bayes\"])\nconst uji = sl.sidebar.slider(\"Porsi data uji (%)\", 10, 40, 25, 5)\nconst buat = () => ({\n  \"Random forest\": sl.ml.RandomForestClassifier({ n_estimators: 80, max_depth: 8 }),\n  \"Regresi logistik\": sl.ml.LogisticRegression(),\n  \"Pohon keputusan\": sl.ml.DecisionTreeClassifier({ max_depth: 4 }),\n  \"KNN\": sl.ml.KNeighborsClassifier({ n_neighbors: 15 }),\n  \"Naive Bayes\": sl.ml.GaussianNB()\n})[jenis]\n\n// cache_data: model hanya dilatih ulang bila pilihan model atau porsi uji berubah\nconst latihModel = sl.cache_data((jenis, uji) => {\n  const [latih, tes] = sl.ml.train_test_split(df, { test_size: uji / 100, stratify: \"churn\" })\n  const model = buat().fit(latih, \"churn\")\n  return { model, tes, pred: model.predict(tes.drop(\"churn\")), prob: model.predict_proba(tes.drop(\"churn\")).col(\"1\") }\n})\nconst { model, tes, pred, prob } = latihModel(jenis, uji)\n\nconst [a, b, c, d] = sl.columns(4)\na.metric(\"Akurasi\", (sl.ml.accuracy_score(tes.churn, pred) * 100).toFixed(1) + \"%\")\nb.metric(\"Precision\", sl.ml.precision_score(tes.churn, pred).toFixed(3))\nc.metric(\"Recall\", sl.ml.recall_score(tes.churn, pred).toFixed(3))\nd.metric(\"ROC AUC\", sl.ml.roc_auc_score(tes.churn, prob).toFixed(3))\n\nconst [k1, k2] = sl.columns(2)\nk1.heatmap(sl.ml.confusion_matrix(tes.churn, pred), { title: \"Matriks kebingungan\" })\nk2.line_chart(sl.ml.roc_curve(tes.churn, prob), { x: \"fpr\", y: \"tpr\", title: \"Kurva ROC\" })\nif (model.importances) sl.bar_chart(model.importances(), { x: \"fitur\", y: \"kepentingan\", horizontal: true, title: \"Fitur paling berpengaruh\" })\n\nsl.expander(\"Validasi silang 5 lipatan\", e => {\n  if (e.button(\"Jalankan validasi silang\")) {\n    const cv = sl.ml.cross_validate(buat(), df, \"churn\", { cv: 5 })\n    e.write(`Akurasi rata-rata **${(cv.mean * 100).toFixed(1)}%** (± ${(cv.std * 100).toFixed(1)}%) dari 5 lipatan.`)\n  }\n})\n\nsl.subheader(\"Coba: bagaimana jika?\")\nconst f = sl.form(\"whatif\")\nconst [x1, x2, x3] = f.columns(3)\nconst baris = {\n  umur: x1.number_input(\"Umur\", { value: 30, min: 18, max: 70 }),\n  kota: x1.selectbox(\"Kota\", df.unique(\"kota\")),\n  paket: x2.selectbox(\"Paket\", [\"Dasar\", \"Plus\", \"Premium\"]),\n  lama_berlangganan: x2.slider(\"Lama berlangganan (bulan)\", 1, 60, 6),\n  tagihan_bulanan: x3.number_input(\"Tagihan bulanan\", { value: 250000, step: 10000 }),\n  jumlah_keluhan: x3.slider(\"Jumlah keluhan\", 0, 8, 2),\n  pakai_aplikasi: f.toggle(\"Memakai aplikasi\", false)\n}\nf.form_submit_button(\"Hitung peluang churn\", { type: \"primary\" })\nconst peluang = model.predict_proba([baris]).col(\"1\").get(0)\nif (peluang >= 0.5) sl.error(`Peluang berhenti: **${(peluang * 100).toFixed(0)}%**. Tawarkan program retensi.`)\nelse sl.success(`Peluang berhenti: **${(peluang * 100).toFixed(0)}%**`)\n"},{"id":"abtest","judul":"Kalkulator Uji A/B","ikon":"🧪","ringkas":"Masukkan angka eksperimen; dapatkan p-value, lift, dan ukuran sampel.","kode":"sl.set_page_config({ page_title: \"Kalkulator Uji A/B\" })\nsl.title(\"🧪 Kalkulator Uji A/B\")\n\nconst [a, b] = sl.columns(2)\na.subheader(\"A (kontrol)\")\nconst nA = a.number_input(\"Pengunjung A\", { value: 5000, min: 1 })\nconst kA = a.number_input(\"Konversi A\", { value: 500, min: 0 })\nb.subheader(\"B (varian)\")\nconst nB = b.number_input(\"Pengunjung B\", { value: 5000, min: 1 })\nconst kB = b.number_input(\"Konversi B\", { value: 570, min: 0 })\nconst alpha = sl.select_slider(\"Tingkat signifikansi (α)\", [0.01, 0.05, 0.1], { value: 0.05 })\n\nconst hasil = sl.stats.ab_test({ A: { n: nA, conversions: kA }, B: { n: nB, conversions: kB } }, { alpha })\nsl.write(hasil)\n\nsl.bar_chart([{ grup: \"A\", konversi: kA / nA }, { grup: \"B\", konversi: kB / nB }], { x: \"grup\", y: \"konversi\", format: \"percent\", labels: true, height: 220 })\n\nsl.subheader(\"Berapa sampel yang dibutuhkan?\")\nconst mde = sl.slider(\"Kenaikan minimal yang ingin dideteksi (relatif, %)\", 1, 50, 10)\nconst n = sl.stats.sample_size_proportion(kA / nA, mde / 100, { relative: true, alpha })\nsl.info(`Untuk mendeteksi kenaikan ${mde}% dari konversi ${(kA / nA * 100).toFixed(1)}% dengan daya uji 80%, dibutuhkan **${n.per_group.toLocaleString(\"id-ID\")} pengunjung per grup** (total ${n.total.toLocaleString(\"id-ID\")}).`)\n"},{"id":"peta_penjualan","judul":"Peta Penjualan","ikon":"🗺️","ringkas":"Gelembung per kota, choropleth per provinsi, dan rute pengiriman. Peta jalan tanpa internet.","kode":"sl.set_page_config({ page_title: \"Peta Penjualan\", page_icon: \"🗺️\", layout: \"wide\" })\nsl.title(\"🗺️ Peta Penjualan\")\nsl.caption(\"Dataset contoh `penjualan`: transaksi toko di enam kota di Tanah Papua. Peta digambar tanpa internet, lengkap dengan 38 provinsi hasil pemekaran 2022.\")\n\nconst df = sl.dataset(\"penjualan\")\nconst semuaKategori = df.unique(\"kategori\")\nconst kategori = sl.sidebar.multiselect(\"Kategori\", semuaKategori, { default: semuaKategori })\nconst ukuran = sl.sidebar.radio(\"Ukuran gelembung\", [\"omzet\", \"transaksi\"], { horizontal: true })\nconst latar = sl.sidebar.selectbox(\"Latar peta\", [\"Offline (batas wilayah)\", \"OpenStreetMap (butuh internet)\"])\nconst tiles = latar.startsWith(\"Open\") ? \"osm\" : null\n\nconst data = df.filter({ kategori })\nif (!data.length) { sl.info(\"Pilih minimal satu kategori.\"); sl.stop() }\n\n// Agregasi per kota: Slak mengenali nama kota dan mencarikan koordinatnya (Timika → Kab. Mimika, dst.)\nconst perKota = data.groupby(\"kota\").agg({ omzet: [\"total\", \"sum\"], transaksi: [\"id_transaksi\", \"nunique\"], pelanggan: [\"pelanggan_id\", \"nunique\"] })\nconst geo = sl.geo.geocode(perKota, \"kota\")\n\nconst [a, b, c] = sl.columns(3)\na.metric(\"Omzet\", \"Rp \" + (data.total.sum() / 1e6).toFixed(1) + \" jt\")\nb.metric(\"Transaksi\", data.id_transaksi.nunique().toLocaleString(\"id-ID\"))\nc.metric(\"Kota\", perKota.length)\n\nconst [t1, t2, t3] = sl.tabs([\"Gelembung per kota\", \"Per provinsi\", \"Jarak antarkota\"])\n\nconst pilih = t1.map(geo, { size: ukuran, color: \"omzet\", tooltip: [\"omzet\", \"transaksi\", \"pelanggan\"], label: \"kota\", tiles, format: \"rp\", title: \"Omzet per kota\", on_select: \"rerun\", key: \"peta_kota\" })\nif (pilih) {\n  t1.subheader(\"Detail \" + pilih.row.kota)\n  const rinci = data.filter({ kota: pilih.row.kota }).groupby(\"kategori\").agg({ omzet: [\"total\", \"sum\"] }).sort_values(\"omzet\", { ascending: false })\n  t1.bar_chart(rinci, { x: \"kategori\", y: \"omzet\", horizontal: true, format: \"compact\", labels: true })\n} else t1.caption(\"Klik sebuah gelembung untuk melihat rincian kategori di kota itu.\")\n\n// Kota → provinsi lewat sl.geo, lalu choropleth provinsi\nconst perProv = geo.assign({ provinsi: r => sl.geo.match(r.wilayah_baku).provinsi })\nt2.choropleth(perProv, { region: \"provinsi\", value: \"omzet\", labels: true, format: \"compact\", tiles, title: \"Omzet per provinsi\", colors: \"teal\" })\nt2.dataframe(perProv.groupby(\"provinsi\").agg({ omzet: [\"omzet\", \"sum\"], kota: [\"kota\", \"list\"] }).sort_values(\"omzet\", { ascending: false }), { format: { omzet: \"rp\" } })\n\nconst asal = t3.selectbox(\"Gudang pusat\", geo.kota.to_list(), { index: 0 })\nconst p = geo.filter({ kota: asal }).row(0)\nconst jarak = geo.assign({ jarak_km: r => Math.round(sl.geo.distance(p.lat, p.lon, r.lat, r.lon)) }).sort_values(\"jarak_km\")\nt3.map(jarak.assign({ asal_lat: () => p.lat, asal_lon: () => p.lon }).filter(r => r.kota !== asal), { lat: \"asal_lat\", lon: \"asal_lon\", to_lat: \"lat\", to_lon: \"lon\", width: \"omzet\", tiles, title: \"Rute pengiriman dari \" + asal, layers: [{ type: \"points\", data: geo, label: \"kota\", radius: 6 }] })\nt3.dataframe(jarak.select([\"kota\", \"jarak_km\", \"omzet\"]), { format: { omzet: \"rp\" } })\n"},{"id":"stok_sqlite","judul":"Stok Barang (SQLite)","ikon":"🗄️","ringkas":"Tabel SQLite yang bisa diedit langsung: ubah, tambah, hapus, lalu simpan.","kode":"sl.set_page_config({ page_title: \"Stok Barang (SQLite)\", page_icon: \"🗄️\" })\nsl.title(\"🗄️ Stok Barang\")\nsl.caption(\"Database SQLite sungguhan yang tersimpan di browser. Ubah sel langsung di tabel, tambah atau hapus baris, lalu tekan Simpan.\")\n\nconst db = await sl.sqlite({ name: \"stok-barang\" })\ndb.run(`CREATE TABLE IF NOT EXISTS barang (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  nama TEXT NOT NULL,\n  kategori TEXT,\n  stok INTEGER DEFAULT 0,\n  harga INTEGER DEFAULT 0\n)`)\nif (db.query(\"SELECT COUNT(*) AS n FROM barang\").n.values[0] === 0) {\n  db.run(`INSERT INTO barang (nama, kategori, stok, harga) VALUES\n    ('Kopi Papua 250g', 'Minuman', 40, 65000), ('Teh Hijau', 'Minuman', 25, 28000),\n    ('Sagu Lempeng', 'Makanan', 60, 25000), ('Abon Ikan', 'Makanan', 12, 55000),\n    ('Kaos Noken', 'Pakaian', 8, 120000)`)\n}\n\nconst data = db.query(\"SELECT * FROM barang ORDER BY id\")\nconst hasil = sl.data_editor(data, {\n  key: \"editor_barang\",\n  num_rows: \"dynamic\",\n  disabled: [\"id\"],\n  column_config: {\n    id: { label: \"ID\" },\n    nama: { label: \"Nama barang\", required: true },\n    kategori: { label: \"Kategori\", options: [\"Minuman\", \"Makanan\", \"Pakaian\", \"Rumah Tangga\"] },\n    stok: { label: \"Stok\", min: 0, step: 1 },\n    harga: { label: \"Harga (Rp)\", min: 0, step: 500 }\n  }\n})\n\nconst e = hasil.edits\nconst jumlah = Object.keys(e.edited_rows).length + e.added_rows.length + e.deleted_rows.length\nconst [k1, k2] = sl.columns([1, 2], { vertical_alignment: \"center\" })\nif (k1.button(\"💾 Simpan ke database\", { type: \"primary\", disabled: jumlah === 0 })) {\n  let n = null\n  try { n = db.save_edits(\"barang\", data, hasil) } catch (err) { sl.error(err.message) }\n  if (n) {\n    delete sl.session_state.editor_barang       // kosongkan catatan perubahan editor\n    sl.toast(`Tersimpan: ${n.diubah} diubah, ${n.ditambah} ditambah, ${n.dihapus} dihapus`, \"✅\")\n    sl.rerun()                                   // jangan taruh sl.rerun() di dalam try/catch\n  }\n}\nk2.caption(jumlah ? `${jumlah} perubahan belum disimpan.` : \"Tidak ada perubahan.\")\n\nsl.subheader(\"Ringkasan dari SQL\")\nsl.dataframe(db.query(`SELECT kategori, COUNT(*) AS jenis, SUM(stok) AS stok, SUM(stok * harga) AS nilai_stok\n  FROM barang GROUP BY kategori ORDER BY nilai_stok DESC`), { format: { nilai_stok: \"rp\" } })\nsl.download_button(\"Unduh database (.db)\", db.blob(), { file_name: \"stok-barang.db\" })\n"},{"id":"inventaris_gudang","judul":"Inventaris Gudang","ikon":"🏭","ringkas":"Aplikasi lengkap: multi-halaman, SQLite yang bisa diedit, target yang bisa diedit, analisis ABC, dan peta gudang.","kode":"sl.set_page_config({ page_title: \"Inventaris Gudang\", page_icon: \"🏭\", layout: \"wide\" })\n\n/* ---------- Database: SQLite yang tersimpan di browser ---------- */\nconst db = await sl.sqlite({ name: \"inventaris-gudang\" })\ndb.run(`CREATE TABLE IF NOT EXISTS gudang (kode TEXT PRIMARY KEY, nama TEXT, kota TEXT, lat REAL, lon REAL)`)\ndb.run(`CREATE TABLE IF NOT EXISTS barang (\n  id INTEGER PRIMARY KEY AUTOINCREMENT, sku TEXT, nama TEXT NOT NULL, kategori TEXT,\n  gudang TEXT REFERENCES gudang(kode), stok INTEGER DEFAULT 0, stok_min INTEGER DEFAULT 0, harga INTEGER DEFAULT 0)`)\ndb.run(`CREATE TABLE IF NOT EXISTS mutasi (id INTEGER PRIMARY KEY AUTOINCREMENT, tanggal TEXT, barang_id INTEGER, jumlah INTEGER)`)\n\nif (db.query(\"SELECT COUNT(*) AS n FROM gudang\").n.values[0] === 0) {\n  db.run(`INSERT INTO gudang VALUES\n    ('JYP', 'Gudang Jayapura', 'Jayapura', -2.5916, 140.6690),\n    ('SRG', 'Gudang Sorong', 'Sorong', -0.8762, 131.2558),\n    ('MRK', 'Gudang Merauke', 'Merauke', -8.4932, 140.4018),\n    ('TMK', 'Gudang Timika', 'Timika', -4.5467, 136.8883)`)\n  const produk = [[\"Kopi Papua 250g\", \"Minuman\", 65000], [\"Teh Hijau\", \"Minuman\", 28000], [\"Air Mineral 12x\", \"Minuman\", 42000],\n    [\"Sagu Lempeng\", \"Makanan\", 25000], [\"Abon Ikan\", \"Makanan\", 55000], [\"Keripik Keladi\", \"Makanan\", 18000],\n    [\"Sabun Cuci\", \"Rumah Tangga\", 35000], [\"Minyak Goreng 2L\", \"Rumah Tangga\", 38000], [\"Kaos Noken\", \"Pakaian\", 120000]]\n  let acak = 7\n  const rnd = () => (acak = (acak * 16807) % 2147483647) / 2147483647\n  const baris = []\n  for (const g of [\"JYP\", \"SRG\", \"MRK\", \"TMK\"]) produk.forEach(([nama, kat, harga], i) => {\n    const min = 10 + Math.round(rnd() * 20)\n    baris.push({ sku: g + \"-\" + String(i + 1).padStart(3, \"0\"), nama, kategori: kat, gudang: g, stok: Math.round(min * (0.3 + rnd() * 2.5)), stok_min: min, harga })\n  })\n  db.insert(\"barang\", baris)\n  // mutasi keluar 6 bulan terakhir (angka negatif = barang keluar)\n  const mut = []\n  for (let id = 1; id <= baris.length; id++) for (let d = 0; d < 180; d += 1 + Math.floor(rnd() * 6)) {\n    const t = new Date(2024, 6, 1 + d)\n    mut.push({ tanggal: t, barang_id: id, jumlah: -(1 + Math.round(rnd() * 8)) })\n  }\n  db.insert(\"mutasi\", mut)\n}\n\nconst rp = v => \"Rp \" + Math.round(v).toLocaleString(\"id-ID\")\nconst stokNilai = () => db.query(`SELECT b.*, g.nama AS nama_gudang, g.kota, g.lat, g.lon, b.stok * b.harga AS nilai,\n  CASE WHEN b.stok < b.stok_min THEN 'Perlu restok' ELSE 'Aman' END AS status\n  FROM barang b JOIN gudang g ON g.kode = b.gudang`)\n\n/* ---------- Halaman 1: Ringkasan ---------- */\nfunction ringkasan(sl) {\n  sl.title(\"🏭 Inventaris Gudang\")\n  const df = stokNilai()\n  const [a, b, c, d] = sl.columns(4)\n  a.metric(\"Jenis barang\", df.length)\n  b.metric(\"Total unit\", df.stok.sum().toLocaleString(\"id-ID\"))\n  c.metric(\"Nilai stok\", rp(df.nilai.sum()))\n  d.metric(\"Perlu restok\", df.filter({ status: \"Perlu restok\" }).length, { delta_color: \"inverse\" })\n\n  const perGudang = df.groupby([\"nama_gudang\", \"kota\", \"lat\", \"lon\"]).agg({ nilai: [\"nilai\", \"sum\"], restok: [\"status\", s => s.filter(x => x === \"Perlu restok\").length] })\n  const [kiri, kanan] = sl.columns([3, 2])\n  kiri.map(perGudang, { size: \"nilai\", color: \"restok\", label: \"nama_gudang\", tooltip: [\"nilai\", \"restok\"], format: \"rp\", title: \"Sebaran gudang (ukuran = nilai stok, warna = jumlah barang perlu restok)\", colors: \"oranye\" })\n  kanan.bar_chart(df.groupby(\"kategori\").agg({ nilai: [\"nilai\", \"sum\"] }).sort_values(\"nilai\", { ascending: false }), { x: \"kategori\", y: \"nilai\", horizontal: true, format: \"compact\", title: \"Nilai stok per kategori\", labels: true })\n  kanan.dataframe(df.filter({ status: \"Perlu restok\" }).select([\"sku\", \"nama\", \"nama_gudang\", \"stok\", \"stok_min\"]).sort_values(\"stok\"), { height: 260 })\n}\n\n/* ---------- Halaman 2: Data barang (SQLite, bisa diedit) ---------- */\nfunction barang(sl) {\n  sl.title(\"📦 Data Barang\")\n  sl.caption(\"Ubah sel, tambah, atau hapus baris, lalu tekan Simpan. Perubahan masuk ke database SQLite di browser.\")\n  const kodeGudang = db.query(\"SELECT kode FROM gudang ORDER BY kode\").kode.to_list()\n  const g = sl.selectbox(\"Gudang\", [\"Semua\", ...kodeGudang])\n  const data = g === \"Semua\" ? db.query(\"SELECT * FROM barang ORDER BY gudang, sku\") : db.query(\"SELECT * FROM barang WHERE gudang = ? ORDER BY sku\", [g])\n  const hasil = sl.data_editor(data, {\n    key: \"ed_barang_\" + g, num_rows: \"dynamic\", disabled: [\"id\"], height: 420,\n    column_config: {\n      id: null,\n      gudang: { label: \"Gudang\", options: kodeGudang, required: true },\n      kategori: { label: \"Kategori\", options: [\"Minuman\", \"Makanan\", \"Rumah Tangga\", \"Pakaian\"] },\n      nama: { label: \"Nama\", required: true },\n      stok: { label: \"Stok\", min: 0, step: 1 }, stok_min: { label: \"Stok minimum\", min: 0, step: 1 },\n      harga: { label: \"Harga\", min: 0, step: 500 }\n    }\n  })\n  const e = hasil.edits\n  const n = Object.keys(e.edited_rows).length + e.added_rows.length + e.deleted_rows.length\n  if (sl.button(`💾 Simpan ${n ? n + \" perubahan\" : \"\"}`, { type: \"primary\", disabled: !n })) {\n    let r = null\n    try { r = db.save_edits(\"barang\", data, hasil) } catch (err) { sl.error(err.message) }\n    if (r) {\n      delete sl.session_state[\"ed_barang_\" + g]\n      sl.toast(`Tersimpan: ${r.diubah} diubah, ${r.ditambah} ditambah, ${r.dihapus} dihapus`, \"✅\")\n      sl.rerun()\n    }\n  }\n}\n\n/* ---------- Halaman 3: Target (tabel biasa yang bisa diedit, disimpan di browser) ---------- */\nfunction target(sl) {\n  sl.title(\"🎯 Target Nilai Stok\")\n  sl.caption(\"Tabel ini bukan dari database: nilainya tersimpan otomatis di browser (persist: true). Ubah angka target, grafik langsung menyesuaikan.\")\n  const realisasi = stokNilai().groupby(\"nama_gudang\").agg({ realisasi: [\"nilai\", \"sum\"] })\n  const awal = new sl.DataFrame(realisasi.nama_gudang.to_list().map(n => ({ gudang: n, target: 15000000 })))\n  const t = sl.data_editor(awal, { key: \"target_gudang\", persist: true, disabled: [\"gudang\"], column_config: { target: { label: \"Target (Rp)\", min: 0, step: 1000000 } } })\n  const banding = t.merge(realisasi, { left_on: \"gudang\", right_on: \"nama_gudang\" })\n    .assign({ capaian: r => r.target ? r.realisasi / r.target : null })\n  sl.bar_chart(banding.melt({ id_vars: [\"gudang\"], value_vars: [\"target\", \"realisasi\"], var_name: \"jenis\", value_name: \"rupiah\" }), { x: \"gudang\", y: \"rupiah\", by: \"jenis\", format: \"compact\", title: \"Target vs realisasi\" })\n  sl.dataframe(banding.select([\"gudang\", \"target\", \"realisasi\", \"capaian\"]), { format: { target: \"rp\", realisasi: \"rp\", capaian: \"percent:0\" }, gradient: [\"capaian\"] })\n}\n\n/* ---------- Halaman 4: Analisis (Slak Data) ---------- */\nfunction analisis(sl) {\n  sl.title(\"📈 Analisis Persediaan\")\n  const stok = stokNilai()\n  const mut = db.query(\"SELECT tanggal, barang_id AS id, -jumlah AS keluar FROM mutasi\")\n  const keluar = mut.groupby(\"id\").agg({ keluar_6bln: [\"keluar\", \"sum\"] })\n  const df = stok.merge(keluar, { on: \"id\", how: \"left\" }).fillna({ keluar_6bln: 0 })\n    .assign({ rata_harian: r => r.keluar_6bln / 180, hari_cukup: r => r.keluar_6bln ? Math.round(r.stok / (r.keluar_6bln / 180)) : null })\n\n  const [t1, t2, t3] = sl.tabs([\"Klasifikasi ABC\", \"Daya tahan stok\", \"Tren barang keluar\"])\n  const abc = sl.analysis.pareto(df.assign({ nilai_keluar: r => r.keluar_6bln * r.harga }), { category: \"nama\", value: \"nilai_keluar\" })\n  t1.combo_chart(abc, { x: \"nama\", bar: \"nilai_keluar\", line: \"persen_kumulatif\", title: \"Pareto nilai barang keluar (kelas A = 80% pertama)\" })\n  t1.dataframe(abc, { format: { nilai_keluar: \"rp\", persen: \"percent:1\", persen_kumulatif: \"percent:0\" } })\n\n  const kritis = df.filter(r => r.hari_cukup != null && r.hari_cukup < 30).sort_values(\"hari_cukup\")\n  t2.metric(\"Barang habis < 30 hari\", kritis.length)\n  t2.histogram(df, { x: \"hari_cukup\", bins: 15, title: \"Sebaran perkiraan hari stok cukup\" })\n  t2.dataframe(kritis.select([\"sku\", \"nama\", \"nama_gudang\", \"stok\", \"rata_harian\", \"hari_cukup\"]), { format: { rata_harian: \"d:1\" } })\n  t2.download_button(\"Unduh daftar restok (Excel)\", kritis.select([\"sku\", \"nama\", \"nama_gudang\", \"stok\", \"stok_min\", \"hari_cukup\"]), { file_name: \"restok.xlsx\" })\n\n  const bulanan = mut.assign({ tanggal: r => new Date(r.tanggal) }).resample(\"tanggal\", \"M\").agg({ keluar: [\"keluar\", \"sum\"] })\n  t3.line_chart(bulanan, { x: \"tanggal\", y: \"keluar\", title: \"Unit keluar per bulan\", trendline: true })\n}\n\nawait sl.navigation([\n  sl.page(\"Ringkasan\", ringkasan, { icon: \"📊\", default: true }),\n  sl.page(\"Data barang\", barang, { icon: \"📦\" }),\n  sl.page(\"Target\", target, { icon: \"🎯\" }),\n  sl.page(\"Analisis\", analisis, { icon: \"📈\" })\n]).run()\n"},{"id":"kuis_interaktif","judul":"Kuis Interaktif","ikon":"🧠","ringkas":"Kuis isian dengan kunci jawaban terlindung (sl.crypto), petunjuk di popover, skor, dan umpan balik bintang.","kode":"sl.set_page_config({ page_title: \"Kuis Interaktif\", page_icon: \"🧠\", theme: { primaryColor: \"#7c3aed\" } })\nsl.title(\"🧠 Kuis Geografi Indonesia\")\nsl.caption(\"Kunci jawaban disimpan sebagai kode acak (sl.crypto.quiz_hash), jadi tidak terbaca di sumber halaman. Kode dibuat dengan menu Alat › Lindungi jawaban kuis.\")\n\n// Kode kunci jawaban: tidak ada jawaban asli yang tertulis di sini.\nconst SOAL = [\n  { tanya: \"Provinsi paling timur di Indonesia, beribu kota di Jayapura?\", kunci: \"sq1$94d63156$m6YDhKYmnlCRaoYjA4ZDce7v\", petunjuk: \"Namanya sama dengan nama pulaunya bagian timur.\" },\n  { tanya: \"Danau terbesar di Indonesia (di Sumatra Utara)?\", kunci: \"sq1$7153d96c$J-3jDgi7lHWNUwyP8N5OiuFL|sq1$d9971ed5$V6nsJdnvi1z0AMwBXbh2AIge\", petunjuk: \"Ada Pulau Samosir di tengahnya.\" },\n  { tanya: \"Satuan mata uang Indonesia?\", kunci: \"sq1$1fa58b09$-SwSvGCRw6qIgkLJjIme6enP|sq1$12c11788$rv_9TH3aSq7Ix7cPwkO8f5dU\", petunjuk: \"Disingkat Rp.\" }\n]\n\nif (!sl.session_state.skor) sl.session_state.skor = {}\nconst skor = sl.session_state.skor\n\nconst mode = sl.segmented_control(\"Mode\", [\"Kuis\", \"Hasil\"], { default: \"Kuis\", key: \"mode\" })\n\nif (mode === \"Kuis\") {\n  SOAL.forEach((s, i) => {\n    sl.subheader(`Soal ${i + 1}`)\n    sl.write(s.tanya)\n    const [a, b] = sl.columns([3, 1], { vertical_alignment: \"bottom\" })\n    const jawab = a.text_input(\"Jawabanmu\", { key: \"j\" + i, label_visibility: \"collapsed\", placeholder: \"Ketik jawaban lalu Enter\" })\n    const pp = b.popover(\"Petunjuk\", { icon: \"💡\" })\n    pp.write(s.petunjuk)\n    if (jawab) {\n      const benar = sl.crypto.quiz_check(jawab, s.kunci)\n      skor[i] = benar\n      if (benar) sl.success(\"Benar! ✨\")\n      else sl.error(\"Belum tepat, coba lagi.\")\n    }\n  })\n} else {\n  const n = Object.values(skor).filter(Boolean).length\n  sl.metric(\"Skor\", `${n} / ${SOAL.length}`, null, { border: true })\n  sl.progress(Math.round(n / SOAL.length * 100), `${Math.round(n / SOAL.length * 100)}% benar`)\n  if (n === SOAL.length) { sl.success(\"Sempurna! 🎉\"); sl.balloons() }\n  sl.write(\"Bagaimana kuis ini?\")\n  const bintang = sl.feedback(\"stars\", { key: \"nilai\" })\n  if (bintang != null) sl.toast(`Terima kasih atas ${bintang + 1} bintang!`, \"⭐\")\n  if (sl.button(\"Ulangi kuis\", { icon: \"🔄\" })) {\n    sl.session_state.skor = {}\n    for (let i = 0; i < SOAL.length; i++) sl.session_state[\"j\" + i] = \"\"\n    sl.session_state.mode = \"Kuis\"\n    sl.rerun()\n  }\n}\n"},{"id":"dasbor_pantau","judul":"Dasbor Pantau Toko","ikon":"📡","ringkas":"Fragment yang memperbarui diri tiap beberapa detik, tabel dengan kolom progress yang bisa dipilih, grafik yang bisa diklik, dan dialog rincian.","kode":"sl.set_page_config({ page_title: \"Dasbor Pantau Toko\", page_icon: \"📡\", layout: \"wide\",\n  menu_items: { About: \"**Dasbor Pantau Toko** — contoh Slak 1.3.1: fragment berkala, tabel terpilih, dialog, dan grafik interaktif.\" } })\nsl.title(\"📡 Dasbor Pantau Toko\")\n\nconst df = sl.dataset(\"penjualan\")\nconst kota = df.unique(\"kota\")\n\n// Pengaturan di popover agar halaman tetap lapang\nconst atur = sl.popover(\"Pengaturan\", { icon: \"⚙️\" })\nconst detik = atur.select_slider(\"Perbarui setiap\", [1, 2, 5, 10], { value: 2, format_func: d => d + \" detik\" })\nconst kanal = atur.pills(\"Kanal\", df.unique(\"kanal\"), { selection_mode: \"multi\", default: df.unique(\"kanal\") })\n\n// Bagian \"langsung\": hanya bagian ini yang dijalankan ulang secara berkala\nconst langsung = sl.fragment((sl) => {\n  const sekarang = new Date()\n  const acak = k => Math.round(50 + 50 * Math.sin(sekarang.getTime() / 4000 + k))\n  sl.caption(\"Diperbarui \" + sekarang.toLocaleTimeString(\"id-ID\") + \" (simulasi data masuk)\")\n  const kol = sl.columns(kota.length)\n  kota.forEach((k, i) => {\n    const riwayat = Array.from({ length: 12 }, (_, j) => Math.round(50 + 50 * Math.sin((sekarang.getTime() - (11 - j) * 4000) / 4000 + i)))\n    kol[i].metric(k, acak(i) + \" trx/jam\", riwayat[11] - riwayat[10], { chart_data: riwayat, chart_type: \"area\", border: true })\n  })\n}, { run_every: detik })\nlangsung()\n\nsl.divider()\n\n// Ringkasan per kota yang bisa dipilih\nconst data = df.filter({ kanal })\nconst ringkas = data.groupby(\"kota\").agg({ omzet: [\"total\", \"sum\"], transaksi: [\"id_transaksi\", \"nunique\"], rata: [\"total\", \"mean\"] })\nconst TARGET = { Jayapura: 140000000, Sorong: 70000000, Biak: 45000000, Manokwari: 42000000, Merauke: 40000000, Timika: 38000000 }\nringkas.target = ringkas.kota.map(k => TARGET[k] || 0)\nringkas.capaian = ringkas.omzet.div(ringkas.target)\n\nconst [kiri, kanan] = sl.columns([3, 2])\nkiri.subheader(\"Per kota\")\nconst pilih = kiri.dataframe(ringkas, {\n  hide_index: true, on_select: \"rerun\", selection_mode: \"multi-row\", key: \"tbl\",\n  column_config: {\n    omzet: sl.column_config.NumberColumn(\"Omzet\", { format: \"rp\" }),\n    target: sl.column_config.NumberColumn(\"Target\", { format: \"rp\" }),\n    rata: sl.column_config.NumberColumn(\"Rata-rata\", { format: \"rp\" }),\n    capaian: sl.column_config.ProgressColumn(\"Capaian\", { min_value: 0, max_value: 1.2, format: \"percent\" }),\n    kota: sl.column_config.Column(\"Kota\", { pinned: true })\n  }\n})\nconst terpilih = pilih.selection.rows.length ? ringkas.iloc(pilih.selection.rows) : ringkas\n\nkanan.subheader(\"Omzet per kategori\")\nconst grafik = kanan.bar_chart(data.filter({ kota: terpilih.kota.values }).groupby(\"kategori\").agg({ omzet: [\"total\", \"sum\"] }),\n  { x: \"kategori\", y: \"omzet\", format: \"rp\", on_select: \"rerun\", key: \"kat\", horizontal: true })\n\n// Dialog rincian kategori yang diklik\nconst rincian = sl.dialog(\"Rincian kategori\", (sl, kat) => {\n  const isi = data.filter({ kategori: kat, kota: terpilih.kota.values })\n  sl.badge(kat, { color: \"violet\" })\n  sl.metric(\"Omzet\", isi.total.sum(), null, { format: \"rp\" })\n  sl.dataframe(isi.groupby(\"produk\").agg({ terjual: [\"jumlah\", \"sum\"], omzet: [\"total\", \"sum\"] }).sort_values(\"omzet\", { ascending: false }),\n    { hide_index: true, column_config: { omzet: sl.column_config.NumberColumn(\"Omzet\", { format: \"rp\" }) } })\n}, { width: \"medium\", on_dismiss: () => { sl.session_state.kat = { selection: { points: [], rows: [] } } } })\nconst klik = grafik.selection.points[0]\nif (klik) rincian(klik.x)\nkanan.caption(\"Klik batang untuk melihat rincian produknya.\")\n"},{"id":"sql_portabel","judul":"Laporan SQL Portabel","ikon":"🐘","ringkas":"Laporan dengan SQL bergaya PostgreSQL (date_trunc, EXTRACT, percentile_cont, FILTER, window function) dan pemeriksa sintaks portabel.","kode":"sl.set_page_config({ page_title: \"Laporan SQL Portabel\", page_icon: \"🐘\" })\nsl.title(\"🐘 Laporan SQL Portabel\")\nsl.markdown(\"Semua kueri di halaman ini berjalan di **SQLite** (di browser) dan juga di **PostgreSQL** tanpa diubah. Mode portabel memperingatkan bila ada sintaks khusus SQLite.\")\n\nconst df = sl.dataset(\"penjualan\")\nconst tabel = { jual: df }\nconst opsi = { portable: true }\n\nsl.header(\"Omzet bulanan\", { divider: \"blue\" })\nconst bulanan = await sl.sql(`\n  SELECT date_trunc('month', tanggal)                         AS bulan,\n         SUM(total)                                           AS omzet,\n         COUNT(DISTINCT pelanggan_id)                         AS pelanggan,\n         percentile_cont(0.5) WITHIN GROUP (ORDER BY total)  AS median_transaksi\n  FROM jual\n  GROUP BY 1\n  ORDER BY 1\n`, tabel, opsi)\nsl.line_chart(bulanan, { x: \"bulan\", y: \"omzet\", format: \"rp\", title: \"Omzet per bulan\" })\n\nsl.header(\"Musim per kuartal\", { divider: \"violet\" })\nconst kuartal = await sl.sql(`\n  SELECT EXTRACT(YEAR FROM tanggal)::int    AS tahun,\n         EXTRACT(QUARTER FROM tanggal)::int AS kuartal,\n         SUM(total)                         AS omzet,\n         SUM(total) FILTER (WHERE kanal = 'Online') AS online\n  FROM jual\n  GROUP BY 1, 2\n  ORDER BY 1, 2\n`, tabel, opsi)\nsl.dataframe(kuartal, { hide_index: true, column_config: { omzet: sl.column_config.NumberColumn(\"Omzet\", { format: \"rp\" }), online: sl.column_config.NumberColumn(\"Online\", { format: \"rp\" }) } })\n\nsl.header(\"Kota dan produk terlaris\", { divider: \"orange\" })\nconst teratas = await sl.sql(`\n  WITH per_kota AS (\n    SELECT kota, produk, SUM(total) AS omzet,\n           RANK() OVER (PARTITION BY kota ORDER BY SUM(total) DESC) AS peringkat\n    FROM jual\n    GROUP BY kota, produk\n  )\n  SELECT kota, string_agg(produk, ', ') AS tiga_teratas, SUM(omzet) AS omzet\n  FROM per_kota\n  WHERE peringkat <= 3\n  GROUP BY kota\n  ORDER BY omzet DESC\n`, tabel, opsi)\nsl.dataframe(teratas, { hide_index: true, column_config: { omzet: sl.column_config.NumberColumn(\"Omzet 3 teratas\", { format: \"rp\" }) } })\n\nsl.header(\"Coba sendiri\", { divider: \"gray\" })\nconst kueri = sl.text_area(\"Tulis kueri (tabel: jual)\", \"SELECT kota, IFNULL(SUM(total), 0) AS omzet\\nFROM jual\\nGROUP BY kota\\nLIMIT 0, 5\", { height: 120 })\nconst masalah = sl.sql.check(kueri)\nif (masalah.length) {\n  sl.warning(\"Kueri ini memakai sintaks khusus SQLite. Ganti agar juga jalan di PostgreSQL:\")\n  sl.table(masalah)\n} else sl.success(\"Kueri ini juga berjalan di PostgreSQL ✓\")\ntry { sl.dataframe(await sl.sql(kueri, tabel)) } catch (e) { sl.error(e.message) }\n"},{"id":"kasir_login","judul":"Kasir dengan Login","ikon":"🏪","ringkas":"Login kasir dan admin dengan password bcrypt, halaman Laporan khusus admin, keranjang belanja, dan riwayat transaksi tersimpan.","kode":"// Kasir Toko dengan Login (Slak 1.4)\n// Masuk sebagai ani / rahasia (admin) atau budi / admin123 (kasir).\n// Hash password dibuat lewat menu Alat › Lindungi password untuk sl.login.\nsl.set_page_config({ page_title: \"Kasir Toko Maju\", page_icon: \":convenience_store:\", layout: \"wide\" })\n\nconst user = await sl.login({\n  users: {\n    ani:  { password: \"$2y$10$qlFsqVOQ2Fg.JoyEeObqGuxcui98Wciz2a5XQWUPHSKXffI4ng3sy\", name: \"Ani Wenda\", role: \"admin\" },\n    budi: { password: \"$2y$10$1CqnlJsbMyNlswHM.h5IJO3XSrqx5dBpnknnMT4Sb/2wV/yyP0uEa\", name: \"Budi Kogoya\", role: \"kasir\" }\n  },\n  title: \":convenience_store: Toko Maju\",\n  caption: \"Masuk dengan akun kasir atau admin\"\n})\n\nconst MENU = [\n  { produk: \"Kopi Wamena\", harga: 25000, ikon: \":coffee:\" },\n  { produk: \"Teh Hijau\", harga: 18000, ikon: \":tea:\" },\n  { produk: \"Roti Abon\", harga: 15000, ikon: \":bread:\" },\n  { produk: \"Kue Lapis\", harga: 12000, ikon: \":cake:\" },\n  { produk: \"Air Mineral\", harga: 6000, ikon: \":droplet:\" }\n]\nconst rp = n => \"Rp \" + Math.round(n).toLocaleString(\"id-ID\")\nif (!sl.local_state.transaksi) sl.local_state.transaksi = []\n\nfunction kasir(sl) {\n  sl.title(\"Kasir :shopping_cart:\")\n  sl.caption(`Petugas: ${sl.user.name} · ${new Date().toLocaleDateString(\"id-ID\", { dateStyle: \"full\" })}`)\n  if (!sl.session_state.keranjang) sl.session_state.keranjang = {}\n  const k = sl.session_state.keranjang\n  const [kiri, kanan] = sl.columns([3, 2])\n  kiri.subheader(\"Menu\")\n  const grid = kiri.columns(3)\n  MENU.forEach((m, i) => {\n    const c = grid[i % 3].container({ border: true })\n    c.markdown(`### ${m.ikon}\\n**${m.produk}**  \\n${rp(m.harga)}`)\n    if (c.button(\"Tambah\", { key: \"add\" + i, icon: \":material/add:\", use_container_width: true })) k[m.produk] = (k[m.produk] || 0) + 1\n  })\n  kanan.subheader(\"Keranjang\")\n  const isi = Object.entries(k).filter(([, n]) => n > 0).map(([produk, n]) => {\n    const m = MENU.find(x => x.produk === produk)\n    return { produk, jumlah: n, subtotal: n * m.harga }\n  })\n  if (!isi.length) { kanan.info(\"Keranjang masih kosong.\", { icon: \":material/info:\" }); return }\n  kanan.dataframe(isi, { hide_index: true, column_config: { subtotal: sl.column_config.NumberColumn(\"Subtotal\", { format: \"rp\" }) } })\n  const total = isi.reduce((a, r) => a + r.subtotal, 0)\n  kanan.metric(\"Total\", rp(total))\n  const [b1, b2] = kanan.columns(2)\n  if (b1.button(\"Bayar\", { type: \"primary\", icon: \":material/payments:\", use_container_width: true })) {\n    sl.local_state.transaksi.push({ waktu: new Date().toISOString(), kasir: sl.user.username, total, item: isi.reduce((a, r) => a + r.jumlah, 0) })\n    sl.session_state.keranjang = {}\n    sl.toast(`Pembayaran ${rp(total)} berhasil :tada:`, { icon: \":white_check_mark:\" })\n    sl.rerun()\n  }\n  if (b2.button(\"Kosongkan\", { icon: \":material/delete:\", use_container_width: true })) { sl.session_state.keranjang = {}; sl.rerun() }\n}\n\nfunction laporan(sl) {\n  sl.require_role(\"admin\")\n  sl.title(\"Laporan :bar_chart:\")\n  const t = sl.DataFrame(sl.local_state.transaksi.length ? sl.local_state.transaksi : [{ waktu: null, kasir: \"-\", total: 0, item: 0 }])\n  const [a, b, c] = sl.columns(3)\n  a.metric(\"Transaksi\", sl.local_state.transaksi.length, null, { border: true })\n  b.metric(\"Omzet\", rp(t.total.sum()), null, { border: true })\n  c.metric(\"Barang terjual\", t.item.sum(), null, { border: true })\n  if (sl.local_state.transaksi.length) {\n    sl.bar_chart(t.groupby(\"kasir\").agg({ omzet: [\"total\", \"sum\"] }), { x: \"kasir\", y: \"omzet\", title: \"Omzet per kasir\", format: \"compact\" })\n    sl.dataframe(t.sort_values(\"waktu\", { ascending: false }), { hide_index: true })\n  } else sl.caption(\"Belum ada transaksi. Coba lakukan penjualan di halaman Kasir.\")\n  if (sl.button(\"Hapus semua transaksi\", { icon: \":material/delete:\" })) { sl.local_state.transaksi = []; sl.rerun() }\n}\n\nsl.navigation([\n  sl.page(\"Kasir\", kasir, { icon: \":material/shopping_cart:\" }),\n  sl.page(\"Laporan\", laporan, { icon: \":material/bar_chart:\", roles: [\"admin\"] })\n]).run()\n"},{"id":"data_dunia","judul":"Dasbor Data Dunia","ikon":"🌐","ringkas":"Indikator Bank Dunia untuk negara ASEAN dengan sl.worldbank: tren, peringkat, tabel, dan simpan untuk luring (butuh internet pertama kali).","kode":"// Dasbor Data Dunia (Slak 1.4): indikator Bank Dunia untuk negara-negara ASEAN.\n// Butuh internet saat pertama kali; sesudahnya data disimpan di browser.\n// Tekan \"Simpan untuk luring\" agar aplikasi jalan tanpa internet di komputer lain.\nsl.set_page_config({ page_title: \"Data Dunia\", page_icon: \":globe_with_meridians:\", layout: \"wide\" })\nsl.title(\"Dasbor Data Dunia :globe_with_meridians:\")\nsl.caption(\"Sumber: World Bank Open Data (CC BY 4.0). Diambil langsung dengan sl.worldbank().\")\n\nconst INDIKATOR = {\n  \"PDB per kapita (US$)\": \"NY.GDP.PCAP.CD\",\n  \"Penduduk\": \"SP.POP.TOTL\",\n  \"Harapan hidup (tahun)\": \"SP.DYN.LE00.IN\",\n  \"Pengguna internet (% penduduk)\": \"IT.NET.USER.ZS\"\n}\nconst NEGARA = { IDN: \"Indonesia\", MYS: \"Malaysia\", THA: \"Thailand\", VNM: \"Vietnam\", PHL: \"Filipina\", SGP: \"Singapura\" }\n\nconst nama = sl.sidebar.selectbox(\"Indikator\", Object.keys(INDIKATOR))\nconst pilih = sl.sidebar.multiselect(\"Negara\", Object.keys(NEGARA), { default: [\"IDN\", \"MYS\", \"THA\", \"VNM\"], format_func: k => NEGARA[k] })\nconst [dari, sampai] = sl.sidebar.slider(\"Tahun\", 1990, 2023, [2000, 2023])\nif (!pilih.length) { sl.info(\"Pilih minimal satu negara.\"); sl.stop() }\n\nlet df\ntry {\n  df = await sl.spinner(\"Mengambil data Bank Dunia…\", () => sl.worldbank(INDIKATOR[nama], { negara: pilih, tahun: [dari, sampai] }))\n} catch (e) {\n  sl.error(\"Data belum bisa diambil. Periksa koneksi internet, lalu muat ulang.\")\n  sl.caption(e.message)\n  sl.stop()\n}\ndf = df.dropna().assign({ negara: r => NEGARA[r.kode] || r.negara })\n\nconst akhir = df.groupby(\"negara\").agg({ tahun: [\"tahun\", \"max\"] })\nconst terbaru = df.merge(akhir, { on: [\"negara\", \"tahun\"] }).sort_values(\"nilai\", { ascending: false })\nconst kolom = sl.columns(Math.min(4, terbaru.length))\nterbaru.head(4).to_records().forEach((r, i) => {\n  const awal = df.query(\"negara == @n\", { n: r.negara }).sort_values(\"tahun\").head(1).to_records()[0]\n  const ubah = awal && awal.nilai ? ((r.nilai / awal.nilai - 1) * 100).toFixed(0) + \"% sejak \" + awal.tahun : null\n  kolom[i].metric(r.negara, r.nilai.toLocaleString(\"id-ID\", { maximumFractionDigits: r.nilai < 1000 ? 1 : 0 }), ubah, { border: true })\n})\n\nconst [tren, peringkat, tabel] = sl.tabs([\":chart_with_upwards_trend: Tren\", \":trophy: Peringkat\", \":material/table: Tabel\"])\ntren.line_chart(df, { x: \"tahun\", y: \"nilai\", by: \"negara\", title: nama, format: \"compact\" })\nperingkat.bar_chart(terbaru, { x: \"negara\", y: \"nilai\", horizontal: true, sort: true, labels: true, format: \"compact\", title: `${nama}, data terbaru` })\ntabel.dataframe(df.pivot_table({ index: \"tahun\", columns: \"negara\", values: \"nilai\", aggfunc: \"first\" }).sort_values(\"tahun\", { ascending: false }))\n\nsl.sidebar.divider()\nsl.sidebar.caption(\"Simpan data untuk dipakai tanpa internet:\")\nsl.sidebar.offline_button({ label: \":floppy_disk: Simpan untuk luring\" })\n"},{"id":"dasbor_duckdb","judul":"Dasbor 1 Juta Transaksi","ikon":"⚡","ringkas":"DuckDB merangkum sampai dua juta transaksi langsung di browser: metrik, tren bulanan per kanal, omzet per kota, dan ekspor Parquet.","kode":"// Dasbor Satu Juta Transaksi (Slak 1.5 · DuckDB)\n// DuckDB membuat dan merangkum 1 juta baris langsung di browser.\nsl.set_page_config({ page_title: \"Dasbor 1 Juta Transaksi\", page_icon: \":zap:\", layout: \"wide\" })\nsl.title(\"Dasbor Satu Juta Transaksi :zap:\")\nsl.caption(\"Semua angka dihitung ulang oleh DuckDB setiap kali filter diubah.\")\n\nconst n = sl.sidebar.select_slider(\"Jumlah transaksi\", [100000, 500000, 1000000, 2000000], { value: 1000000, format_func: x => x.toLocaleString(\"id-ID\") })\nconst kanal = sl.sidebar.multiselect(\"Kanal\", [\"Online\", \"Toko\", \"Grosir\"], { default: [\"Online\", \"Toko\", \"Grosir\"] })\nif (!kanal.length) { sl.info(\"Pilih minimal satu kanal.\"); sl.stop() }\n\n// Data buatan yang mirip aslinya: porsi kota berbeda, ramai di akhir tahun, Online terus tumbuh.\nconst JUAL = `SELECT\n  CASE WHEN h < 30 THEN 'Jayapura' WHEN h < 50 THEN 'Sorong' WHEN h < 65 THEN 'Merauke'\n       WHEN h < 78 THEN 'Timika' WHEN h < 90 THEN 'Biak' ELSE 'Manokwari' END AS kota,\n  CASE WHEN k < 50 - bln * 2 THEN 'Toko' WHEN k < 88 THEN 'Online' ELSE 'Grosir' END AS kanal,\n  tanggal,\n  ROUND((20000 + (i * 7919) % 480000) * (1 + 0.35 * cos(2 * pi() * (bln - 12) / 12)), -2) AS total\nFROM (SELECT i, hash(i) % 100 AS h, hash(i * 31 + 7) % 100 AS k,\n             DATE '2024-01-01' + CAST(hash(i * 17 + 3) % 366 AS INTEGER) AS tanggal,\n             month(DATE '2024-01-01' + CAST(hash(i * 17 + 3) % 366 AS INTEGER)) AS bln\n      FROM range(${n}) t(i))`\nconst where = `WHERE kanal IN (${kanal.map(k => `'${k}'`).join(\", \")})`\n\nconst t0 = performance.now()\nconst [ringkas, bulanan, perKota] = await Promise.all([\n  sl.duckdb(`SELECT COUNT(*) AS transaksi, SUM(total) AS omzet, AVG(total) AS rata FROM (${JUAL}) ${where}`),\n  sl.duckdb(`SELECT date_trunc('month', tanggal) AS bulan, kanal, SUM(total) AS omzet FROM (${JUAL}) ${where} GROUP BY 1, 2 ORDER BY 1`),\n  sl.duckdb(`SELECT kota, SUM(total) AS omzet, COUNT(*) AS transaksi FROM (${JUAL}) ${where} GROUP BY kota ORDER BY omzet DESC`)\n])\nconst ms = Math.round(performance.now() - t0)\n\nconst r = ringkas.to_records()[0]\nconst [a, b, c, d] = sl.columns(4)\na.metric(\"Transaksi\", r.transaksi.toLocaleString(\"id-ID\"), null, { border: true })\nb.metric(\"Omzet\", \"Rp \" + (r.omzet / 1e9).toLocaleString(\"id-ID\", { maximumFractionDigits: 1 }) + \" M\", null, { border: true })\nc.metric(\"Rata-rata\", \"Rp \" + Math.round(r.rata).toLocaleString(\"id-ID\"), null, { border: true })\nd.metric(\"Waktu hitung\", ms + \" md\", null, { border: true })\n\nconst [kiri, kanan] = sl.columns([3, 2])\nkiri.line_chart(bulanan, { x: \"bulan\", y: \"omzet\", by: \"kanal\", title: \"Omzet per bulan\", format: \"compact\" })\nkanan.bar_chart(perKota, { x: \"kota\", y: \"omzet\", horizontal: true, sort: true, title: \"Omzet per kota\", format: \"compact\" })\n\nif (sl.button(\"Simpan ringkasan per kota sebagai Parquet\", { icon: \":material/download:\" })) {\n  const pq = await sl.duckdb.to_file(`SELECT kota, SUM(total) AS omzet FROM (${JUAL}) ${where} GROUP BY kota`, \"per_kota.parquet\")\n  sl.download_button(\"Unduh per_kota.parquet\", pq, { file_name: \"per_kota.parquet\" })\n}\n"},{"id":"portofolio_profil","judul":"Templat Portofolio","ikon":"🧑‍💼","ringkas":"Halaman profil data analyst dengan keahlian, kontak, dan kartu proyek, plus satu halaman analisis. Ganti isinya, lalu ekspor dan unggah.","kode":"// Templat Portofolio Data Analyst (Slak 1.6)\n// Ganti isi PROFIL dan PROYEK dengan milikmu, lalu Ekspor folder situs (Bab 21) dan unggah.\nsl.set_page_config({ page_title: \"Portofolio · Nama Kamu\", page_icon: \":bar_chart:\", layout: \"wide\" })\n\nconst PROFIL = {\n  nama: \"Nama Kamu\",\n  peran: \"Data Analyst · Jayapura\",\n  ringkas: \"Saya mengubah data penjualan dan operasional menjadi keputusan yang bisa dijalankan. Terbiasa dengan SQL, analisis statistik, dan dasbor interaktif.\",\n  keahlian: [\"SQL\", \"Slak\", \"Excel\", \"Statistik\", \"Visualisasi data\", \"Python (pandas)\"],\n  kontak: [[\"Email\", \"mailto:nama@contoh.id\"], [\"LinkedIn\", \"https://www.linkedin.com/\"], [\"GitHub\", \"https://github.com/\"]]\n}\nconst PROYEK = [\n  { judul: \"Analisis Penjualan Toko\", ringkas: \"Tren omzet, kota terbaik, dan segmentasi pelanggan RFM dari 3.278 transaksi.\", tag: [\"SQL\", \"RFM\", \"Dasbor\"], halaman: \"Analisis Penjualan\" },\n  { judul: \"Prediksi Churn Pelanggan\", ringkas: \"Model regresi logistik untuk menemukan pelanggan yang berisiko berhenti berlangganan.\", tag: [\"Machine learning\", \"Statistik\"], tautan: \"churn.html\" },\n  { judul: \"Uji A/B Halaman Promo\", ringkas: \"Apakah desain baru menaikkan pembelian? Uji proporsi dua sampel dan ukuran efek.\", tag: [\"Uji A/B\", \"Statistik\"], tautan: \"uji-ab.html\" }\n]\n\nfunction beranda(sl) {\n  const [kiri, kanan] = sl.columns([1, 3])\n  kiri.html(`<div style=\"width:120px;height:120px;border-radius:50%;background:var(--slak-primary,#0f766e);color:#fff;display:grid;place-items:center;font:600 44px/1 sans-serif\">${PROFIL.nama.split(\" \").map(k => k[0]).join(\"\").slice(0, 2)}</div>`)\n  kanan.title(PROFIL.nama)\n  kanan.markdown(`**${PROFIL.peran}**\\n\\n${PROFIL.ringkas}`)\n  kanan.markdown(PROFIL.keahlian.map(k => `:blue-badge[${k}]`).join(\" \"))\n  const tombol = kanan.columns(PROFIL.kontak.length + 2)\n  PROFIL.kontak.forEach(([label, url], i) => tombol[i].link_button(label, url))\n\n  sl.divider()\n  sl.header(\"Proyek\")\n  const kolom = sl.columns(3)\n  PROYEK.forEach((p, i) => {\n    const k = kolom[i % 3].container({ border: true })\n    k.subheader(p.judul)\n    k.write(p.ringkas)\n    k.markdown(p.tag.map(t => `:gray-badge[${t}]`).join(\" \"))\n    if (p.halaman) k.page_link(p.halaman, { label: \"Lihat analisis\", icon: \":material/arrow_forward:\" })\n    else k.link_button(\"Buka proyek\", p.tautan)\n  })\n}\n\nfunction analisis(sl) {\n  const df = sl.dataset(\"penjualan\")   // ganti dengan: await sl.read_csv(\"penjualan.csv\")\n  sl.title(\"Analisis Penjualan Toko\")\n  sl.caption(\"Data: 3.278 transaksi 2023–2024 dari enam kota di Papua (data contoh Slak).\")\n  const [a, b, c] = sl.columns(3)\n  a.metric(\"Omzet\", \"Rp \" + (df.col(\"total\").sum() / 1e6).toLocaleString(\"id-ID\", { maximumFractionDigits: 0 }) + \" jt\", null, { border: true })\n  b.metric(\"Transaksi\", df.col(\"id_transaksi\").nunique().toLocaleString(\"id-ID\"), null, { border: true })\n  c.metric(\"Pelanggan\", df.col(\"pelanggan_id\").nunique().toLocaleString(\"id-ID\"), null, { border: true })\n  const [kiri, kanan] = sl.columns([3, 2])\n  kiri.line_chart(df.resample(\"tanggal\", \"M\").agg({ total: \"sum\" }), { x: \"tanggal\", y: \"total\", title: \"Omzet per bulan\", format: \"compact\" })\n  kanan.bar_chart(df.groupby(\"kota\").agg({ omzet: [\"total\", \"sum\"] }), { x: \"kota\", y: \"omzet\", horizontal: true, sort: true, title: \"Omzet per kota\", format: \"compact\" })\n  // Temuan dihitung dari data, jadi tetap benar saat datanya diganti\n  const kota = df.groupby(\"kota\").agg({ omzet: [\"total\", \"sum\"] }).sort_values(\"omzet\", { ascending: false }).to_records()\n  const porsi = Math.round(kota[0].omzet / df.col(\"total\").sum() * 100)\n  const th = df.assign({ tahun: r => r.tanggal.getFullYear() }).pivot_table({ index: \"kanal\", columns: \"tahun\", values: \"total\", aggfunc: \"sum\" }).to_records()\n  const tumbuh = th.map(r => { const t = Object.keys(r).filter(k => k !== \"kanal\").sort(); return { kanal: r.kanal, naik: Math.round((r[t[t.length - 1]] / r[t[0]] - 1) * 100) } }).sort((a, b) => b.naik - a.naik)\n  const bln = df.resample(\"tanggal\", \"M\").agg({ total: \"sum\" }).sort_values(\"total\", { ascending: false }).to_records()[0]\n  sl.subheader(\"Temuan\")\n  sl.markdown(`1. **${kota[0].kota}** menyumbang ${porsi}% omzet.\\n2. Omzet tertinggi di ${bln.tanggal.toLocaleDateString(\"id-ID\", { month: \"long\", year: \"numeric\" })}.\\n3. Kanal **${tumbuh[0].kanal}** tumbuh ${tumbuh[0].naik}% dalam setahun, ${tumbuh[1].kanal} ${tumbuh[1].naik}%.`)\n}\n\nfunction tentang(sl) {\n  sl.title(\"Tentang saya\")\n  sl.markdown(\"Ceritakan latar belakangmu, alat yang kamu kuasai, dan masalah yang ingin kamu selesaikan. Perekrut biasanya membaca bagian ini paling lama.\")\n  sl.subheader(\"Pengalaman\")\n  sl.table({ Tahun: [\"2025–sekarang\", \"2023–2025\"], Peran: [\"Analis Data, Toko Contoh\", \"Staf Administrasi Penjualan\"], Pencapaian: [\"Dasbor mingguan menggantikan laporan manual\", \"Merapikan data 3 cabang ke satu basis data\"] })\n}\n\nsl.navigation([\n  sl.page(\"Beranda\", beranda, { icon: \":material/home:\", default: true }),\n  sl.page(\"Analisis Penjualan\", analisis, { icon: \":material/insights:\" }),\n  sl.page(\"Tentang\", tentang, { icon: \":material/person:\" })\n], { position: \"top\" }).run()\n"},{"id":"templat_dasbor_penjualan","judul":"Templat Dasbor Penjualan","ikon":"📊","ringkas":"Dasbor siap pakai: filter periode, wilayah, dan kanal; angka utama dibanding periode sebelumnya; tren, kategori, wilayah, dan produk terlaris. Ganti datanya dengan CSV milikmu.","kode":"// Templat Dasbor Penjualan (Slak 1.7)\n// Cara memakai datamu sendiri:\n//   1. Ganti baris DATA dengan: const DATA = await sl.read_csv(\"penjualan.csv\")\n//   2. Sesuaikan nama kolom di KOLOM dengan nama kolom di CSV-mu.\nsl.set_page_config({ page_title: \"Dasbor Penjualan\", page_icon: \":bar_chart:\", layout: \"wide\" })\n\nconst KOLOM = { tanggal: \"tanggal\", nilai: \"total\", kategori: \"kategori\", wilayah: \"kota\", kanal: \"kanal\", produk: \"produk\", transaksi: \"id_transaksi\" }\nconst DATA = sl.dataset(\"penjualan\")\n\nconst df = DATA.copy()\ndf.bulan = df[KOLOM.tanggal].dt.strftime(\"%Y-%m\")\nconst bulan = df.bulan.unique().sort()\n\n// ---------- Filter ----------\nsl.sidebar.header(\"Filter\")\nconst [awal, akhir] = sl.sidebar.select_slider(\"Periode\", bulan, { value: [bulan[Math.max(0, bulan.length - 12)], bulan[bulan.length - 1]] })\nconst wilayah = sl.sidebar.multiselect(\"Wilayah\", df[KOLOM.wilayah].unique().sort(), { placeholder: \"Semua wilayah\" })\nconst semuaKanal = df[KOLOM.kanal].unique()\nconst kanal = sl.sidebar.pills(\"Kanal\", semuaKanal, { selection_mode: \"multi\", default: semuaKanal })\n\nconst cocok = r => (!wilayah.length || wilayah.includes(r[KOLOM.wilayah])) && kanal.includes(r[KOLOM.kanal])\nconst iA = bulan.indexOf(awal), iB = bulan.indexOf(akhir), n = iB - iA + 1\nconst periodeLalu = bulan.slice(Math.max(0, iA - n), iA)\nconst kini = df.filter(r => r.bulan >= awal && r.bulan <= akhir && cocok(r))\nconst lalu = df.filter(r => periodeLalu.includes(r.bulan) && cocok(r))\n\n// ---------- Judul dan angka utama ----------\nsl.title(\"📊 Dasbor Penjualan\")\nsl.caption(`${awal} sampai ${akhir} · ${kini.length.toLocaleString(\"id-ID\")} baris · dibanding ${periodeLalu.length} bulan sebelumnya`)\n\nconst ubah = (a, b) => b ? (a >= b ? \"+\" : \"\") + ((a - b) / b * 100).toFixed(1) + \"%\" : null\nconst omzet = kini[KOLOM.nilai].sum(), omzetLalu = lalu[KOLOM.nilai].sum()\nconst trx = kini[KOLOM.transaksi].nunique(), trxLalu = lalu[KOLOM.transaksi].nunique()\nconst [k1, k2, k3, k4] = sl.columns(4)\nk1.metric(\"Omzet\", omzet, ubah(omzet, omzetLalu), { format: \"rp\", border: true })\nk2.metric(\"Transaksi\", trx, ubah(trx, trxLalu), { border: true })\nk3.metric(\"Rata-rata per transaksi\", trx ? omzet / trx : 0, ubah(trx ? omzet / trx : 0, trxLalu ? omzetLalu / trxLalu : 0), { format: \"rp\", border: true })\nk4.metric(\"Kategori terlaris\", kini.length ? kini.groupby(KOLOM.kategori).agg({ v: [KOLOM.nilai, \"sum\"] }).sort_values(\"v\", { ascending: false }).iloc(0)[KOLOM.kategori] : \"-\", null, { border: true })\n\n// ---------- Grafik ----------\nconst [ringkas, rinci] = sl.tabs([\"Ringkasan\", \"Data\"])\nconst tren = kini.groupby(\"bulan\").agg({ omzet: [KOLOM.nilai, \"sum\"] })\nringkas.line_chart(tren, { x: \"bulan\", y: \"omzet\", format: \"rp\", title: \"Omzet per bulan\", height: 260 })\n\nconst [kiri, kanan] = ringkas.columns(2)\nkiri.bar_chart(kini.groupby(KOLOM.kategori).agg({ omzet: [KOLOM.nilai, \"sum\"] }).sort_values(\"omzet\", { ascending: false }),\n  { x: KOLOM.kategori, y: \"omzet\", format: \"rp\", horizontal: true, title: \"Per kategori\" })\nkanan.bar_chart(kini.groupby(KOLOM.wilayah).agg({ omzet: [KOLOM.nilai, \"sum\"] }).sort_values(\"omzet\", { ascending: false }),\n  { x: KOLOM.wilayah, y: \"omzet\", format: \"rp\", horizontal: true, title: \"Per wilayah\" })\n\nringkas.subheader(\"10 produk terlaris\")\nconst top = kini.groupby(KOLOM.produk).agg({ omzet: [KOLOM.nilai, \"sum\"], transaksi: [KOLOM.transaksi, \"nunique\"] }).sort_values(\"omzet\", { ascending: false }).head(10)\ntop.porsi = top.omzet.div(omzet || 1)\nringkas.dataframe(top, { hide_index: true, column_config: {\n  omzet: sl.column_config.NumberColumn(\"Omzet\", { format: \"rp\" }),\n  porsi: sl.column_config.ProgressColumn(\"Porsi omzet\", { min_value: 0, max_value: Math.max(0.01, ...top.porsi.values), format: \"percent\" })\n} })\n\nrinci.dataframe(kini, { hide_index: true, height: 420 })\nrinci.download_button(\"Unduh data terpilih (CSV)\", kini, { file_name: `penjualan_${awal}_${akhir}.csv`, icon: \":material/download:\" })\n"},{"id":"templat_dasbor_pelanggan","judul":"Templat Dasbor Pelanggan & Churn","ikon":"👥","ringkas":"Siapa yang berhenti berlangganan, dan kenapa? Angka churn per paket, kota, dan jumlah keluhan, plus formulir coba model (sl.ml_demo) untuk menebak churn satu pelanggan.","kode":"// Templat Dasbor Pelanggan & Churn (Slak 1.7)\n// Ganti DATA dengan datamu (await sl.read_csv(\"pelanggan.csv\")). Kolom TARGET berisi 1 = berhenti, 0 = bertahan.\nsl.set_page_config({ page_title: \"Dasbor Pelanggan\", page_icon: \"👥\", layout: \"wide\" })\n\nconst DATA = sl.dataset(\"pelanggan\")\nconst TARGET = \"churn\"\nconst ID = \"pelanggan_id\"\n\nsl.sidebar.header(\"Filter\")\nconst paket = sl.sidebar.multiselect(\"Paket\", DATA.paket.unique().sort(), { placeholder: \"Semua paket\" })\nconst kota = sl.sidebar.multiselect(\"Kota\", DATA.kota.unique().sort(), { placeholder: \"Semua kota\" })\nconst df = DATA.filter(r => (!paket.length || paket.includes(r.paket)) && (!kota.length || kota.includes(r.kota)))\n\nsl.title(\"👥 Dasbor Pelanggan & Churn\")\nsl.caption(`${df.length.toLocaleString(\"id-ID\")} dari ${DATA.length.toLocaleString(\"id-ID\")} pelanggan`)\n\nconst persen = v => (v * 100).toFixed(1).replace(\".\", \",\") + \"%\"\nconst [k1, k2, k3, k4] = sl.columns(4)\nk1.metric(\"Pelanggan\", df.length.toLocaleString(\"id-ID\"), null, { border: true })\nk2.metric(\"Tingkat churn\", persen(df[TARGET].mean()), null, { border: true, help: \"Bagian pelanggan yang berhenti berlangganan\" })\nk3.metric(\"Rata-rata tagihan\", df.tagihan_bulanan.mean(), null, { format: \"rp\", border: true })\nk4.metric(\"Rata-rata keluhan\", df.jumlah_keluhan.mean().toFixed(2).replace(\".\", \",\"), null, { border: true })\n\nconst [lihat, model] = sl.tabs([\"Pola churn\", \"Coba model\"])\nconst churnPer = kol => {\n  const g = df.groupby(kol).agg({ churn_persen: [TARGET, \"mean\"], pelanggan: [ID, \"count\"] })\n  g.churn_persen = g.churn_persen.mul(100).round(1)\n  return g\n}\nconst [a, b] = lihat.columns(2)\na.bar_chart(churnPer(\"paket\"), { x: \"paket\", y: \"churn_persen\", title: \"Churn per paket (%)\" })\nb.bar_chart(churnPer(\"kota\").sort_values(\"churn_persen\", { ascending: false }), { x: \"kota\", y: \"churn_persen\", horizontal: true, title: \"Churn per kota (%)\" })\nlihat.line_chart(churnPer(\"jumlah_keluhan\"), { x: \"jumlah_keluhan\", y: \"churn_persen\", title: \"Makin banyak keluhan, makin banyak yang berhenti (%)\", height: 240 })\nlihat.caption(\"Grafik menunjukkan hubungan, belum tentu sebab-akibat.\")\n\nmodel.write(\"Model dilatih dari data di atas (tanpa kolom ID), lalu dicoba dengan nilai yang kamu pilih.\")\nconst m = sl.cache_resource(() => sl.ml.RandomForestClassifier({ n_estimators: 40, max_depth: 6 }))()\nconst hasil = model.ml_demo(m, DATA.drop(ID), { target: TARGET, labels: { 0: \"Bertahan\", 1: \"Berhenti\" }, title: \"Akankah pelanggan ini berhenti?\" })\nif (hasil && hasil.proba && hasil.proba[\"1\"] > 0.5) model.warning(\"Pelanggan seperti ini berisiko berhenti. Pertimbangkan tindak lanjut, misalnya menghubungi untuk menyelesaikan keluhannya.\")\n"},{"id":"templat_dasbor_sdm","judul":"Templat Dasbor SDM","ikon":"🧑‍🤝‍🧑","ringkas":"Dasbor karyawan: jumlah orang, gaji rata-rata per departemen, pelatihan dan kinerja, sebaran pendidikan, serta perkiraan gaji dengan regresi linear.","kode":"// Templat Dasbor SDM (Slak 1.7)\n// Ganti DATA dengan datamu (await sl.read_csv(\"karyawan.csv\")) dan sesuaikan nama kolomnya.\nsl.set_page_config({ page_title: \"Dasbor SDM\", page_icon: \"🧑‍🤝‍🧑\", layout: \"wide\" })\n\nconst DATA = sl.dataset(\"karyawan\")\nconst dep = sl.sidebar.selectbox(\"Departemen\", [\"Semua\", ...DATA.departemen.unique().sort()])\nconst df = dep === \"Semua\" ? DATA : DATA.filter({ departemen: [dep] })\n\nsl.title(\"🧑‍🤝‍🧑 Dasbor SDM\")\nconst [k1, k2, k3, k4] = sl.columns(4)\nk1.metric(\"Karyawan\", df.length, null, { border: true })\nk2.metric(\"Rata-rata gaji\", \"Rp\" + df.gaji_juta.mean().toFixed(1).replace(\".\", \",\") + \" jt\", null, { border: true })\nk3.metric(\"Rata-rata pengalaman\", df.pengalaman_tahun.mean().toFixed(1).replace(\".\", \",\") + \" th\", null, { border: true })\nk4.metric(\"Rata-rata kinerja\", df.nilai_kinerja.mean().toFixed(0), null, { border: true })\n\nconst [kiri, kanan] = sl.columns(2)\nkiri.bar_chart(DATA.groupby(\"departemen\").agg({ gaji_juta: [\"gaji_juta\", \"mean\"] }).round(2), { x: \"departemen\", y: \"gaji_juta\", title: \"Rata-rata gaji per departemen (juta)\" })\nkanan.bar_chart(df.pendidikan.value_counts(), { x: \"pendidikan\", y: \"jumlah\", title: \"Pendidikan terakhir\" })\nsl.scatter_chart(df, { x: \"jam_pelatihan\", y: \"nilai_kinerja\", color: \"departemen\", title: \"Jam pelatihan dan nilai kinerja\", height: 300 })\nconst r = sl.stats.pearsonr(df.jam_pelatihan.values, df.nilai_kinerja.values)\nsl.caption(`Korelasi jam pelatihan dan kinerja: r = ${r.statistic.toFixed(2)} (p = ${r.pvalue < 0.001 ? \"< 0,001\" : r.pvalue.toFixed(3)}).`)\n\nsl.divider()\nconst lr = sl.ml.LinearRegression().fit(DATA.drop([\"karyawan_id\", \"gaji_juta\"]), DATA.gaji_juta)\nsl.ml_demo(lr, DATA, { title: \"Perkiraan gaji (juta rupiah)\", key: \"gaji\", columns: 3 })\n"},{"id":"komponen_rating","judul":"Komponen Kustom: Rating Bintang","ikon":"⭐","ringkas":"Membuat widget sendiri dengan HTML dan JavaScript lalu memakainya seperti widget Slak lain. Nilai dari komponen kembali ke kode Slak lewat Slak.component.setValue.","kode":"// Komponen kustom dua arah (Slak 1.7)\n// HTML di bawah berjalan di dalam bingkai sendiri. Ia menerima args dari Slak\n// dan mengirim nilai kembali dengan Slak.component.setValue(...).\nconst BINTANG = `\n<style>\n  span { font-size: 32px; cursor: pointer; color: #d6d3d1; transition: transform .1s }\n  span.on { color: #f59e0b }  span:hover { transform: scale(1.15) }\n  p { margin: 0 0 2px; color: var(--slak-fg); font-size: 14px }\n</style>\n<p id=\"t\"></p><div id=\"b\"></div>\n<script>\n  let nilai = 0\n  function gambar(maks) {\n    const b = document.getElementById(\"b\"); b.innerHTML = \"\"\n    for (let i = 1; i <= maks; i++) {\n      const s = document.createElement(\"span\")\n      s.textContent = \"★\"; s.className = i <= nilai ? \"on\" : \"\"\n      s.onclick = () => { nilai = i; gambar(maks); Slak.component.setValue(i) }\n      b.append(s)\n    }\n  }\n  Slak.component.onRender(args => {\n    if (!nilai) nilai = args.awal\n    document.getElementById(\"t\").textContent = args.label\n    gambar(args.maks)\n  })\n<\\/script>`\n\nconst rating = (label, o) => sl.component(BINTANG, { args: { label, maks: o.maks || 5, awal: o.awal || 0 }, key: o.key, default: o.awal || 0 })\n\nsl.title(\"⭐ Survei Kepuasan\")\nconst layanan = rating(\"Bagaimana pelayanan kami?\", { key: \"layanan\", awal: 4 })\nconst harga = rating(\"Bagaimana harga kami?\", { key: \"harga\", maks: 10, awal: 7 })\nsl.write(`Pelayanan: **${layanan}/5** · Harga: **${harga}/10**`)\nif (layanan <= 2) sl.warning(\"Terima kasih atas masukannya. Kami akan memperbaiki pelayanan.\")\n"},{"id":"uji_aplikasi","judul":"Uji Aplikasi Otomatis","ikon":"✅","ringkas":"Menguji aplikasi kasir dengan sl.testing: mengisi widget, menekan tombol, lalu memeriksa hasilnya. Hasil setiap uji tampil hijau (lolos) atau merah (gagal).","kode":"// Uji aplikasi otomatis dengan sl.testing (Slak 1.7)\n// Biasanya aplikasi disimpan di berkas sendiri, lalu diuji dengan sl.testing.run(\"kasir.slak\").\nconst KASIR = `\nconst harga = sl.number_input(\"Harga\", { value: 50000, step: 1000 })\nconst jumlah = sl.number_input(\"Jumlah\", { value: 1, min_value: 1 })\nconst member = sl.checkbox(\"Member (diskon 10%)\")\nconst total = harga * jumlah * (member ? 0.9 : 1)\nsl.metric(\"Total\", total)\nif (sl.button(\"Bayar\")) sl.success(\"Lunas: Rp\" + total.toLocaleString(\"id-ID\"))\n`\nconst { expect } = sl.testing\nsl.title(\"✅ Uji Aplikasi Kasir\")\n\nawait sl.testing.test(\"total awal sama dengan harga\", async () => {\n  const at = await sl.testing.run(KASIR)\n  expect(at.metric(\"Total\").value).toBe(50000)\n  at.close()\n})\nawait sl.testing.test(\"tiga barang untuk member didiskon 10%\", async () => {\n  const at = await sl.testing.run(KASIR)\n  at.number_input(\"Jumlah\").set_value(3)\n  await at.checkbox(\"Member (diskon 10%)\").check().run()\n  expect(at.metric(\"Total\").value).toBe(135000)\n  at.close()\n})\nawait sl.testing.test(\"tombol Bayar menampilkan pesan lunas\", async () => {\n  const at = await sl.testing.run(KASIR)\n  await at.button(\"Bayar\").click().run()\n  expect(at.success[0].value).toContain(\"Lunas\")\n  at.close()\n})\nsl.testing.summary()\n"},{"id":"laporan_sql","judul":"Laporan SQL (Markdown)","ikon":"📝","ringkas":"Laporan berbentuk tulisan: paragraf Markdown dengan angka yang diisi otomatis dari blok SQL, tabel, dan grafik. Cocok untuk laporan bulanan yang dikirim ke atasan.","kode":"// Laporan SQL (Slak 1.7): tulis laporan seperti dokumen biasa.\n// Blok ```sql dijalankan; {{ nama.kolom }} di teks diganti nilai hasilnya.\nsl.set_page_config({ page_title: \"Laporan Penjualan\" })\nconst TAHUN = sl.select_slider(\"Tahun\", [\"2023\", \"2024\"], { value: \"2024\" })\n\nawait sl.report(`\n# Laporan Penjualan ${TAHUN}\n\nSepanjang ${TAHUN} toko mencatat **{{ ringkas.transaksi }} transaksi** dengan omzet **{{ ringkas.omzet | rp }}**,\natau rata-rata **{{ ringkas.rata | rp }}** per transaksi.\n\nKota dengan omzet terbesar adalah **{{ kota.kota }}**, menyumbang **{{ kota.porsi | persen }}** dari seluruh omzet.\nKategori terlaris adalah **{{ kategori.kategori }}**.\n\n\\`\\`\\`sql name=ringkas hide\nSELECT COUNT(*) AS transaksi, SUM(total) AS omzet, AVG(total) AS rata\nFROM penjualan WHERE strftime('%Y', tanggal) = :tahun\n\\`\\`\\`\n\n## Omzet per kota\n\n\\`\\`\\`sql name=kota chart=bar x=kota y=omzet format=rp horizontal=true\nSELECT kota, SUM(total) AS omzet,\n       SUM(total) * 1.0 / (SELECT SUM(total) FROM penjualan WHERE strftime('%Y', tanggal) = :tahun) AS porsi\nFROM penjualan WHERE strftime('%Y', tanggal) = :tahun\nGROUP BY kota ORDER BY omzet DESC\n\\`\\`\\`\n\n## Tren bulanan\n\n\\`\\`\\`sql chart=line x=bulan y=omzet format=rp height=240\nSELECT strftime('%m', tanggal) AS bulan, SUM(total) AS omzet\nFROM penjualan WHERE strftime('%Y', tanggal) = :tahun GROUP BY bulan ORDER BY bulan\n\\`\\`\\`\n\n## Kategori\n\n\\`\\`\\`sql name=kategori show=both chart=pie x=kategori y=omzet code\nSELECT kategori, SUM(total) AS omzet, COUNT(*) AS transaksi\nFROM penjualan WHERE strftime('%Y', tanggal) = :tahun GROUP BY kategori ORDER BY omzet DESC\n\\`\\`\\`\n\n*Dibuat dengan Slak. Data: dataset contoh penjualan.*\n`, { tables: { penjualan: sl.dataset(\"penjualan\") }, params: { tahun: TAHUN } })\n"},{"id":"analisis_sel","judul":"Analisis Bertahap (mode sel)","ikon":"🧩","ringkas":"Kode dibagi menjadi sel dengan baris // %%. Di Slak Studio, tekan Shift+Enter untuk menjalankan sampai sel tempat kursor berada, seperti notebook.","kode":"// Analisis bertahap dengan mode sel (Slak 1.7)\n// Letakkan kursor di sebuah sel lalu tekan Shift+Enter: Slak menjalankan kode dari awal sampai sel itu.\nsl.title(\"🧩 Analisis Pelanggan Bertahap\")\n\n// %% 1. Muat data\nconst df = sl.dataset(\"pelanggan\")\nsl.caption(`${df.length} pelanggan, ${df.columns.length} kolom`)\nsl.dataframe(df.head(5), { hide_index: true })\n\n// %% 2. Bersihkan dan tambah kolom\ndf.kelompok_umur = sl.cut(df.umur, [17, 25, 35, 50, 70], { labels: [\"18–25\", \"26–35\", \"36–50\", \"51+\"] })\nsl.write(\"Kolom baru: **kelompok_umur**\")\n\n// %% 3. Ringkas\nconst per = df.groupby(\"kelompok_umur\").agg({ pelanggan: [\"pelanggan_id\", \"count\"], churn: [\"churn\", \"mean\"] })\nper.churn = per.churn.mul(100).round(1)\nsl.dataframe(per, { hide_index: true })\n\n// %% 4. Grafik\nsl.bar_chart(per, { x: \"kelompok_umur\", y: \"churn\", title: \"Churn per kelompok umur (%)\" })\n"}];
